46	/**
47	 * A switch(string) java code will be compiled to two switches in class code.
48	 * Sometimes, android's d8/r8 will make some further modification.
49	 * 1st switch could be changed to ifs to reduce size of dex.
50	 * 2nd switch could be flattened and removed if there are many cases using a same block.
51	 */
52	@JadxVisitor(
53			name = "SwitchOverStringVisitor",
54			desc = "Restore switch over string",
55			runAfter = IfRegionVisitor.class,
56			runBefore = ReturnVisitor.class
57	)
58	public class SwitchOverStringVisitor extends AbstractVisitor implements IRegionIterativeVisitor {
59		private static final Integer DEFAULT_NUM_VALUE = -1;
60	
61		@Override
62		public void visit(MethodNode mth) throws JadxException {
63			if (!CodeFeaturesAttr.contains(mth, CodeFeature.SWITCH)) {
64				return;
65			}
66			DepthRegionTraversal.traverseIterative(mth, this);
67		}
68	
69		@Override
70		public boolean visitRegion(MethodNode mth, IRegion region) {
71			if (region instanceof SwitchRegion || region instanceof IfRegion) {
72				return restoreSwitchOverString(mth, region);
73			}
74			return false;
75		}
76	
77		private boolean restoreSwitchOverString(MethodNode mth, IRegion part1Region) {
78			try {
79				InsnNode strHashInsn = BlockUtils.getLastInsn(RegionUtils.getFirstBlockNode(part1Region));
80				InvokeNode hashcodeInv = strHashInsn == null ? null : getStrHashcodeInvokeInsn(strHashInsn.getArg(0));
81				InsnArg strArg = hashcodeInv == null ? null : hashcodeInv.getInstanceArg();
82				if (strArg == null || !strArg.isRegister()) {
83					return false;
84				}
85	
86				SwitchData data = new SwitchData(mth, part1Region);
87				data.setHashcodeInvokeInsn(hashcodeInv);
88				data.setStrArg((RegisterArg) strArg);
89	
90				IContainer nextContainer = RegionUtils.getNextContainer(mth, part1Region);
91				boolean isPart1Switch = part1Region instanceof SwitchRegion;
92				boolean isPart2Switch = nextContainer instanceof SwitchRegion;
93				if (isPart2Switch) {
94					SwitchRegion part2Region = (SwitchRegion) nextContainer;
95					InsnNode part2SwInsn = BlockUtils.getLastInsnWithType(part2Region.getHeader(), InsnType.SWITCH);
96					if (part2SwInsn == null || !part2SwInsn.getArg(0).isRegister()) {
97						return false;
98					}
99					data.setType(isPart1Switch ? SwitchStringType.SWITCH_SWITCH : SwitchStringType.IF_SWITCH);
100					data.setPart2Region(part2Region);
101					data.setNumArg((RegisterArg) part2SwInsn.getArg(0));
102				} else if (isPart1Switch) {
103					data.setType(SwitchStringType.SINGLE_SWITCH);
104				} else {
105					return false;
106				}
107	
108				if (!collectPart1RegionCases(data)) {
109					return false;
110				}
111				if (!prepareMergedSwitchCases(data) || !replaceWithMergedSwitch(data)) {
112					mth.addWarnComment("Failed to restore switch over string. Please report as a decompilation issue");
113					return false;
114				}
115				return true;
116			} catch (StackOverflowError | Exception e) {
117				mth.addWarnComment("Failed to restore switch over string. Please report as a decompilation issue", e);
118				return false;
119			}
120		}
121	
122		/**
123		 * store str and num/caseBlock in switchData
124		 * validate:
125		 * - case key is hashcode of strValue
126		 * - case block is str.equals compare
127		 * - str compare thenBlock is num assign (SWITCH_SWITCH and IF_SWITCH)
128		 */
129		private static boolean collectPart1RegionCases(SwitchData data) {
130			// a map of hashcode keys and case blocks
131			Map<Integer, BlockNode> hashCases = new LinkedHashMap<>();
132			if (data.getType() == SwitchStringType.IF_SWITCH) {
133				IfRegion part1If = (IfRegion) data.getPart1Region();
134				BlockNode part2Header = Objects.requireNonNull(data.getPart2Region()).getHeader();
135				RegisterArg strHashArg = null;
136				BlockNode ifStartBlock = part1If.getConditionBlocks().get(0);
137				BlockNode hashCmpBlock = getOnlyOneInsnBlock(ifStartBlock);
138				do {
139					IfNode ifNode = (IfNode) BlockUtils.getLastInsnWithType(hashCmpBlock, InsnType.IF);
140					if (ifNode == null || (ifNode.getOp() != IfOp.NE && ifNode.getOp() != IfOp.EQ)) {
141						return false;
142					}
143					boolean isNE = ifNode.getOp() == IfOp.NE;
144					BlockNode thenBlock = getOnlyOneInsnBlock(isNE ? ifNode.getElseBlock() : ifNode.getThenBlock());
145					BlockNode elseBlock = getOnlyOneInsnBlock(isNE ? ifNode.getThenBlock() : ifNode.getElseBlock());
146					if (thenBlock == null || elseBlock == null || !ifNode.getArg(0).isRegister() || !ifNode.getArg(1).isLiteral()) {
147						return false;
148					}
149					RegisterArg tmpStrHashArg = (RegisterArg) ifNode.getArg(0);
150					LiteralArg literalArg = (LiteralArg) ifNode.getArg(1);
151					if (strHashArg == null) {
152						strHashArg = tmpStrHashArg;
153					} else if (!strHashArg.sameCodeVar(tmpStrHashArg)) {
154						return false;
155					}
156					hashCases.put((int) literalArg.getLiteral(), thenBlock);
157					hashCmpBlock = elseBlock;
158					// end of part1If: no further hash compare, next block is part2switch
159					Integer fallbackNum = extractConstNumber(data, BlockUtils.getLastInsn(hashCmpBlock));
160					BlockNode nextBlock = BlockUtils.getNextBlock(hashCmpBlock);
161					if (elseBlock == part2Header || (DEFAULT_NUM_VALUE.equals(fallbackNum) && nextBlock == part2Header)) {
162						break;
163					}
164				} while (true);
165			} else {
166				SwitchRegion part1Switch = (SwitchRegion) data.getPart1Region();
167				SwitchInsn swInsn = (SwitchInsn) BlockUtils.getLastInsnWithType(part1Switch.getHeader(), InsnType.SWITCH);
168				Objects.requireNonNull(swInsn);
169				for (int i = 0; i < swInsn.getKeys().length; i++) {
170					BlockNode caseBlock = getOnlyOneInsnBlock(swInsn.getTargetBlocks()[i]);
171					if (caseBlock == null) {
172						return false;
173					}
174					hashCases.put(swInsn.getKeys()[i], caseBlock);
175				}
176			}
177	
178			// save to switchData
179			data.setCases(new ArrayList<>(hashCases.size()));
180			for (Integer hashcode : hashCases.keySet()) {
181				BlockNode caseBlock = hashCases.get(hashcode);
182				IfNode ifStrEqualsInsn = (IfNode) BlockUtils.getLastInsnWithType(caseBlock, InsnType.IF);
183				if (!isIfStringEqualsInsn(ifStrEqualsInsn)) {
184					return false;
185				}
186				do {
187					InsnNode strEqualsInsn = InsnUtils.getWrappedInsn(ifStrEqualsInsn.getArg(0));
188					Objects.requireNonNull(strEqualsInsn);
189					InsnArg strArg = strEqualsInsn.getArg(0);
190					InsnArg valArg = strEqualsInsn.getArg(1);
191					Object strValue = InsnUtils.getConstValueByArg(data.getMth().root(), valArg);
192					if (!data.getStrArg().equals(strArg) || !(strValue instanceof String) || strValue.hashCode() != hashcode) {
193						return false;
194					}
195					boolean isCmpNE = (ifStrEqualsInsn.getOp() == IfOp.EQ) != ifStrEqualsInsn.getArg(1).isTrue();
196					BlockNode thenBlock = isCmpNE ? ifStrEqualsInsn.getElseBlock() : ifStrEqualsInsn.getThenBlock();
197					BlockNode elseBlock = isCmpNE ? ifStrEqualsInsn.getThenBlock() : ifStrEqualsInsn.getElseBlock();
198					Integer numValue = null;
199					if (data.getType() == SwitchStringType.SWITCH_SWITCH || data.getType() == SwitchStringType.IF_SWITCH) {
200						InsnNode numInsn = BlockUtils.getLastInsn(getOnlyOneInsnBlock(thenBlock));
201						RegisterArg numArg = Objects.requireNonNull(data.getNumArg());
202						if (thenBlock != null && (numInsn == null || numInsn.getType() == InsnType.SWITCH)) {
203							// num is assigned before 1st region. find nearest assign
204							BlockNode iDom = thenBlock.getIDom();
205							while (iDom != null && numValue == null) {
206								for (InsnNode insn : iDom.getInstructions()) {
207									numValue = extractConstNumber(data, insn);
208								}
209								iDom = iDom.getIDom();
210							}
211							if (numValue == null) {
212								return false;
213							}
214						} else if (numInsn != null && numArg.sameCodeVar(numInsn.getResult())) {
215							numValue = extractConstNumber(data, numInsn);
216						} else {
217							return false;
218						}
219					}
220					// store str and num assign in switchData
221					data.getCases().add(new CaseData(strValue, numValue, thenBlock));
222					// there may be more string compare (same hashcode)
223					BlockNode nextIfBlock = getOnlyOneInsnBlock(elseBlock);
224					ifStrEqualsInsn = (IfNode) BlockUtils.getLastInsnWithType(nextIfBlock, InsnType.IF);
225				} while (isIfStringEqualsInsn(ifStrEqualsInsn));
226			}
227			return true;
228		}
