230		/**
231		 * create cases according to part2Region (part1Region if is SINGLE_SWITCH).
232		 * replace keys with strings.
233		 */
234		private static boolean prepareMergedSwitchCases(SwitchData data) {
235			SwitchRegion part2Region = data.getPart2Region();
236			List<CaseData> cases = data.getCases();
237			List<SwitchRegion.CaseInfo> newCases = new ArrayList<>();
238			data.setNewCases(newCases);
239			if (data.getType() == SwitchStringType.SWITCH_SWITCH || data.getType() == SwitchStringType.IF_SWITCH) {
240				// group by num
241				Map<Integer, List<Object>> casesMap = new HashMap<>(cases.size());
242				for (CaseData caseData : cases) {
243					casesMap.computeIfAbsent(caseData.getCodeNum(), v -> new ArrayList<>()).add(caseData.getStrValue());
244				}
245				for (SwitchRegion.CaseInfo caseInfo : Objects.requireNonNull(part2Region).getCases()) {
246					SwitchRegion.CaseInfo newCase = new SwitchRegion.CaseInfo(new ArrayList<>(), caseInfo.getContainer());
247					for (Object key : caseInfo.getKeys()) {
248						Integer intKey = unwrapIntKey(key);
249						if (key != SwitchRegion.DEFAULT_CASE_KEY) {
250							List<Object> strings = casesMap.remove(Objects.requireNonNull(intKey));
251							if (strings == null || strings.isEmpty()) {
252								return false;
253							}
254							newCase.getKeys().addAll(strings);
255						} else {
256							// last case. add all remaining strings
257							for (List<Object> strings : casesMap.values()) {
258								newCase.getKeys().addAll(strings);
259							}
260							casesMap.clear();
261							newCase.getKeys().add(SwitchRegion.DEFAULT_CASE_KEY);
262						}
263					}
264					newCases.add(newCase);
265				}
266				if (!casesMap.isEmpty()) {
267					data.getMth().addWarnComment("switch over string: strings are not added: " + casesMap.values());
268				}
269			} else if (data.getType() == SwitchStringType.SINGLE_SWITCH) {
270				SwitchRegion part1Region = (SwitchRegion) data.getPart1Region();
271				SwitchInsn swInsn = (SwitchInsn) BlockUtils.getLastInsnWithType(part1Region.getHeader(), InsnType.SWITCH);
272				BlockNode defBlock = Objects.requireNonNull(swInsn).getDefTargetBlock();
273				if (defBlock != null) {
274					cases.add(new CaseData(SwitchRegion.DEFAULT_CASE_KEY, DEFAULT_NUM_VALUE, defBlock));
275				}
276				CaseData lastCaseData = null;
277				for (CaseData caseData : cases) {
278					if (lastCaseData != null && lastCaseData.getCode() == caseData.getCode()) {
279						// combine cases whose blocks are the same
280						SwitchRegion.CaseInfo lastInfo = Objects.requireNonNull(ListUtils.last(newCases));
281						lastInfo.getKeys().add(caseData.getStrValue());
282					} else {
283						IContainer container = RegionUtils.getBlockContainer(part1Region, caseData.getCode());
284						if (container == null) {
285							return false;
286						}
287						SwitchRegion.CaseInfo newInfo = new SwitchRegion.CaseInfo(new ArrayList<>(), container);
288						newInfo.getKeys().add(caseData.getStrValue());
289						newCases.add(newInfo);
290					}
291					lastCaseData = caseData;
292				}
293			}
294			return true;
295		}
