297		/** replace with new switch. remove original code */
298		private static boolean replaceWithMergedSwitch(SwitchData data) {
299			MethodNode mth = data.getMth();
300			IRegion part1Region = data.getPart1Region();
301			IRegion part1Parent = part1Region.getParent();
302			SwitchRegion part2Region = data.getPart2Region();
303			List<InsnNode> keptInsns = new ArrayList<>();
304			BlockNode newHeader;
305			if (data.getType() == SwitchStringType.SWITCH_SWITCH || data.getType() == SwitchStringType.SINGLE_SWITCH) {
306				newHeader = ((SwitchRegion) part1Region).getHeader();
307			} else {
308				newHeader = Objects.requireNonNull(part2Region).getHeader();
309			}
310			// use string arg directly in switch
311			InsnNode swInsn = BlockUtils.getLastInsnWithType(newHeader, InsnType.SWITCH);
312			InsnNode newSwInsn = Objects.requireNonNull(swInsn).copyWithoutResult();
313			newSwInsn.replaceArg(swInsn.getArg(0), data.getStrArg().duplicate());
314			BlockUtils.replaceInsn(mth, newHeader, swInsn, newSwInsn);
315			keptInsns.add(newSwInsn);
316	
317			SwitchRegion replaceRegion = new SwitchRegion(part1Parent, newHeader);
318			for (SwitchRegion.CaseInfo caseInfo : data.getNewCases()) {
319				IContainer container = caseInfo.getContainer();
320				RegionUtils.visitBlocks(mth, container, b -> keptInsns.addAll(b.getInstructions()));
321				replaceRegion.addCase(Collections.unmodifiableList(caseInfo.getKeys()), container);
322				replaceRegion.updateParent(container, replaceRegion);
323			}
324			if (!part1Parent.replaceSubBlock(part1Region, replaceRegion)) {
325				return false;
326			}
327	
328			// remove original code
329			try {
330				List<InsnNode> removeInsns = RegionUtils.collectInsns(mth, part1Region);
331				if (part2Region != null) {
332					removeInsns.addAll(RegionUtils.collectInsns(mth, part2Region));
333					part2Region.getParent().getSubBlocks().remove(part2Region);
334				}
335				removeInsns.removeAll(keptInsns);
336				removeInsns.forEach(i -> i.add(AFlag.REMOVE));
337				// may be assigned before 1st region
338				RegisterArg numArg = data.getNumArg();
339				if (numArg != null) {
340					for (SSAVar ssaVar : numArg.getSVar().getCodeVar().getSsaVars()) {
341						InsnNode assignInsn = ssaVar.getAssignInsn();
342						if (assignInsn != null) {
343							assignInsn.add(AFlag.REMOVE);
344						}
345						for (RegisterArg useArg : ssaVar.getUseList()) {
346							InsnNode parentInsn = useArg.getParentInsn();
347							if (parentInsn != null) {
348								parentInsn.add(AFlag.REMOVE);
349							}
350						}
351						mth.removeSVar(ssaVar);
352					}
353				}
354				InsnRemover.removeAllMarked(mth);
355				InsnRemover.remove(mth, data.getHashcodeInvokeInsn());
356			} catch (StackOverflowError | Exception e) {
357				mth.addWarnComment("Failed to clean up code after switch over string restore", e);
358			}
359			return true;
360		}
