362		private static @Nullable Integer extractConstNumber(SwitchData switchData, @Nullable InsnNode numInsn) {
363			if (numInsn == null || numInsn.getArgsCount() != 1) {
364				return null;
365			}
366			Object constVal = InsnUtils.getConstValueByArg(switchData.getMth().root(), numInsn.getArg(0));
367			if (constVal instanceof LiteralArg) {
368				RegisterArg numArg = switchData.getNumArg();
369				if (numArg != null && numArg.sameCodeVar(numInsn.getResult())) {
370					return (int) ((LiteralArg) constVal).getLiteral();
371				}
372			}
373			return null;
374		}
375	
376		private static Integer unwrapIntKey(Object key) {
377			if (key instanceof Integer) {
378				return (Integer) key;
379			}
380			if (key instanceof FieldNode) {
381				EncodedValue encodedValue = ((FieldNode) key).get(JadxAttrType.CONSTANT_VALUE);
382				if (encodedValue != null && encodedValue.getType() == EncodedType.ENCODED_INT) {
383					return (Integer) encodedValue.getValue();
384				}
385				return null;
386			}
387			return null;
388		}
