390		private static @Nullable InvokeNode getStrHashcodeInvokeInsn(InsnArg arg) {
391			InsnNode insn = null;
392			if (arg.isRegister()) {
393				insn = ((RegisterArg) arg).getAssignInsn();
394			} else if (arg.isInsnWrap()) {
395				insn = ((InsnWrapArg) arg).getWrapInsn();
396			}
397			if (insn != null && insn.getType() == InsnType.INVOKE) {
398				InvokeNode invInsn = (InvokeNode) insn;
399				if (invInsn.getCallMth().getRawFullId().equals("java.lang.String.hashCode()I")) {
400					return invInsn;
401				}
402			}
403			return null;
404		}
405	
406		private static boolean isIfStringEqualsInsn(InsnNode ifInsn) {
407			if (ifInsn != null && ifInsn.getType() == InsnType.IF && ifInsn.getArgsCount() == 2) {
408				InsnNode wrapped = InsnUtils.getWrappedInsn(ifInsn.getArg(0));
409				return wrapped != null && wrapped.getType() == InsnType.INVOKE
410						&& ((InvokeNode) wrapped).getCallMth().getRawFullId().equals("java.lang.String.equals(Ljava/lang/Object;)Z");
411			}
412			return false;
413		}
414	
415		private static @Nullable BlockNode getOnlyOneInsnBlock(BlockNode b) {
416			while (b != null) {
417				int size = b.getInstructions().size();
418				if (size == 0) {
419					b = BlockUtils.getNextBlock(b);
420					continue;
421				}
422				return size == 1 ? b : null;
423			}
424			return null;
425		}
