427		private static final class SwitchData {
428			private final MethodNode mth;
429			private SwitchStringType type = SwitchStringType.SWITCH_SWITCH;
430			// first switch/if region
431			private final IRegion part1Region;
432			// second switch region, null if type is SINGLE_SWITCH
433			private @Nullable SwitchRegion part2Region;
434			// each case is a str in part1Region, with its num or code block
435			private List<CaseData> cases;
436			private List<SwitchRegion.CaseInfo> newCases;
437			private RegisterArg numArg;
438			private RegisterArg strArg;
439			private InsnNode hashcodeInvokeInsn;
440	
441			private SwitchData(MethodNode mth, IRegion part1Region) {
442				this.mth = mth;
443				this.part1Region = part1Region;
444			}
445	
446			public SwitchStringType getType() {
447				return type;
448			}
449	
450			public void setType(SwitchStringType type) {
451				this.type = type;
452			}
453	
454			public List<CaseData> getCases() {
455				return cases;
456			}
457	
458			public void setCases(List<CaseData> cases) {
459				this.cases = cases;
460			}
461	
462			public List<SwitchRegion.CaseInfo> getNewCases() {
463				return newCases;
464			}
465	
466			public void setNewCases(List<SwitchRegion.CaseInfo> cases) {
467				this.newCases = cases;
468			}
469	
470			public MethodNode getMth() {
471				return mth;
472			}
473	
474			public IRegion getPart1Region() {
475				return part1Region;
476			}
477	
478			public @Nullable SwitchRegion getPart2Region() {
479				return part2Region;
480			}
481	
482			public void setPart2Region(@Nullable SwitchRegion part2Region) {
483				this.part2Region = part2Region;
484			}
485	
486			public @Nullable RegisterArg getNumArg() {
487				return numArg;
488			}
489	
490			public void setNumArg(RegisterArg numArg) {
491				this.numArg = numArg;
492			}
493	
494			public RegisterArg getStrArg() {
495				return strArg;
496			}
497	
498			public void setStrArg(RegisterArg strArg) {
499				this.strArg = strArg;
500			}
501	
502			public InsnNode getHashcodeInvokeInsn() {
503				return hashcodeInvokeInsn;
504			}
505	
506			public void setHashcodeInvokeInsn(InsnNode hashcodeInvokeInsn) {
507				this.hashcodeInvokeInsn = hashcodeInvokeInsn;
508			}
509		}
