511		private static final class CaseData {
512			private final Object strValue;
513			private final BlockNode code;
514			private final Integer codeNum;
515	
516			private CaseData(Object strValue, Integer codeNum, BlockNode code) {
517				this.strValue = strValue;
518				this.code = code;
519				this.codeNum = codeNum;
520			}
521	
522			public Object getStrValue() {
523				return strValue;
524			}
525	
526			public @Nullable BlockNode getCode() {
527				return code;
528			}
529	
530			public Integer getCodeNum() {
531				return codeNum;
532			}
533	
534			@Override
535			public String toString() {
536				return "CaseData{" + strValue + '}';
537			}
538		}
539	
540		private enum SwitchStringType {
541			SINGLE_SWITCH,
542			IF_SWITCH,
543			SWITCH_SWITCH
544		}
545	}
