45	@JadxVisitor(
46			name = "LoopRegionVisitor",
47			desc = "Convert 'while' loops to 'for' loops (indexed or for-each)",
48			runBefore = ProcessVariables.class
49	)
50	public class LoopRegionVisitor extends AbstractVisitor implements IRegionVisitor {
51		private static final Logger LOG = LoggerFactory.getLogger(LoopRegionVisitor.class);
52	
53		@Override
54		public void visit(MethodNode mth) {
55			DepthRegionTraversal.traverse(mth, this);
56			IfRegionVisitor.processIfRequested(mth);
57		}
58	
59		@Override
60		public boolean enterRegion(MethodNode mth, IRegion region) {
61			if (region instanceof LoopRegion) {
62				if (processLoopRegion(mth, (LoopRegion) region)) {
63					// optimize `if` block after instructions remove
64					mth.add(AFlag.REQUEST_IF_REGION_OPTIMIZE);
65				}
66			}
67			return true;
68		}
69	
70		private static boolean processLoopRegion(MethodNode mth, LoopRegion loopRegion) {
71			if (loopRegion.isConditionAtEnd()) {
72				return false;
73			}
74			IfCondition condition = loopRegion.getCondition();
75			if (condition == null) {
76				return false;
77			}
78			if (checkForIndexedLoop(mth, loopRegion, condition)) {
79				return true;
80			}
81			return checkIterableForEach(mth, loopRegion, condition);
82		}
83	
84		/**
85		 * Check for indexed loop.
86		 */
87		private static boolean checkForIndexedLoop(MethodNode mth, LoopRegion loopRegion, IfCondition condition) {
88			BlockNode loopEndBlock = loopRegion.getInfo().getEnd();
89			InsnNode incrInsn = BlockUtils.getLastInsn(BlockUtils.skipSyntheticPredecessor(loopEndBlock));
90			if (incrInsn == null) {
91				return false;
92			}
93			RegisterArg incrArg = incrInsn.getResult();
94			if (incrArg == null
95					|| incrArg.getSVar() == null
96					|| !incrArg.getSVar().isUsedInPhi()) {
97				return false;
98			}
99			List<PhiInsn> phiInsnList = incrArg.getSVar().getUsedInPhi();
100			if (phiInsnList.size() != 1) {
101				return false;
102			}
103			PhiInsn phiInsn = phiInsnList.get(0);
104			if (phiInsn.getArgsCount() != 2
105					|| !phiInsn.containsVar(incrArg)
106					|| incrArg.getSVar().getUseCount() != 1) {
107				return false;
108			}
109			RegisterArg arg = phiInsn.getResult();
110			List<RegisterArg> condArgs = condition.getRegisterArgs();
111			if (!condArgs.contains(arg) || arg.getSVar().isUsedInPhi()) {
112				return false;
113			}
114			RegisterArg initArg = phiInsn.getArg(0);
115			InsnNode initInsn = initArg.getAssignInsn();
116			if (initInsn == null
117					|| initInsn.contains(AFlag.DONT_GENERATE)
118					|| initArg.getSVar().getUseCount() != 1) {
119				return false;
120			}
121			if (!usedOnlyInLoop(mth, loopRegion, arg)) {
122				return false;
123			}
124			// can't make loop if argument from increment instruction is assign in loop
125			List<RegisterArg> args = new ArrayList<>();
126			incrInsn.getRegisterArgs(args);
127			for (RegisterArg iArg : args) {
128				try {
129					if (assignOnlyInLoop(mth, loopRegion, iArg)) {
130						return false;
131					}
132				} catch (StackOverflowError error) {
133					throw new JadxOverflowException("LoopRegionVisitor.assignOnlyInLoop endless recursion");
134				}
135			}
136	
137			// all checks passed
138			initInsn.add(AFlag.DONT_GENERATE);
139			incrInsn.add(AFlag.DONT_GENERATE);
140	
141			LoopType arrForEach = checkArrayForEach(mth, loopRegion, initInsn, incrInsn, condition);
142			loopRegion.setType(arrForEach != null ? arrForEach : new ForLoop(initInsn, incrInsn));
143			return true;
144		}
145	
146		private static LoopType checkArrayForEach(MethodNode mth, LoopRegion loopRegion, InsnNode initInsn, InsnNode incrInsn,
147				IfCondition condition) {
148			if (!(incrInsn instanceof ArithNode)) {
149				return null;
150			}
151			ArithNode arithNode = (ArithNode) incrInsn;
152			if (arithNode.getOp() != ArithOp.ADD) {
153				return null;
154			}
155			InsnArg lit = incrInsn.getArg(1);
156			if (!lit.isLiteral() || ((LiteralArg) lit).getLiteral() != 1) {
157				return null;
158			}
159			if (initInsn.getType() != InsnType.CONST
160					|| !initInsn.getArg(0).isLiteral()
161					|| ((LiteralArg) initInsn.getArg(0)).getLiteral() != 0) {
162				return null;
163			}
164	
165			InsnArg condArg = incrInsn.getArg(0);
166			if (!condArg.isRegister()) {
167				return null;
168			}
169			SSAVar sVar = ((RegisterArg) condArg).getSVar();
170			List<RegisterArg> args = sVar.getUseList();
171			if (args.size() != 3) {
172				return null;
173			}
174			condArg = InsnUtils.getRegFromInsn(args, InsnType.IF);
175			if (condArg == null) {
176				return null;
177			}
178			RegisterArg arrIndex = InsnUtils.getRegFromInsn(args, InsnType.AGET);
179			if (arrIndex == null) {
180				return null;
181			}
182			InsnNode arrGetInsn = arrIndex.getParentInsn();
183			if (arrGetInsn == null || arrGetInsn.containsWrappedInsn()) {
184				return null;
185			}
186			if (!condition.isCompare()) {
187				return null;
188			}
189			Compare compare = condition.getCompare();
190			if (compare.getOp() != IfOp.LT || compare.getA() != condArg) {
191				return null;
192			}
193			InsnNode len;
194			InsnArg bCondArg = compare.getB();
195			if (bCondArg.isInsnWrap()) {
196				len = ((InsnWrapArg) bCondArg).getWrapInsn();
197			} else if (bCondArg.isRegister()) {
198				len = ((RegisterArg) bCondArg).getAssignInsn();
199			} else {
200				return null;
201			}
202			if (len == null || len.getType() != InsnType.ARRAY_LENGTH) {
203				return null;
204			}
205			InsnArg arrayArg = len.getArg(0);
206			if (!arrayArg.equals(arrGetInsn.getArg(0))) {
207				return null;
208			}
209			RegisterArg iterVar = arrGetInsn.getResult();
210			if (iterVar != null) {
211				if (!usedOnlyInLoop(mth, loopRegion, iterVar)) {
212					return null;
213				}
214			} else {
215				if (!arrGetInsn.contains(AFlag.WRAPPED)) {
216					return null;
217				}
218				// create new variable and replace wrapped insn
219				InsnArg wrapArg = BlockUtils.searchWrappedInsnParent(mth, arrGetInsn);
220				if (wrapArg == null || wrapArg.getParentInsn() == null) {
221					mth.addWarnComment("checkArrayForEach: Wrapped insn not found: " + arrGetInsn);
222					return null;
223				}
224				iterVar = mth.makeSyntheticRegArg(wrapArg.getType());
225				InsnNode parentInsn = wrapArg.getParentInsn();
226				parentInsn.replaceArg(wrapArg, iterVar.duplicate());
227				parentInsn.rebindArgs();
228			}
229	
230			// array for each loop confirmed
231			incrInsn.getResult().add(AFlag.DONT_GENERATE);
232			condArg.add(AFlag.DONT_GENERATE);
233			bCondArg.add(AFlag.DONT_GENERATE);
234			arrGetInsn.add(AFlag.DONT_GENERATE);
235			compare.getInsn().add(AFlag.DONT_GENERATE);
236	
237			ForEachLoop forEachLoop = new ForEachLoop(iterVar, len.getArg(0));
238			forEachLoop.injectFakeInsns(loopRegion);
239			if (InsnUtils.dontGenerateIfNotUsed(len)) {
240				InsnRemover.remove(mth, len);
241			}
242			CodeShrinkVisitor.shrinkMethod(mth);
243			return forEachLoop;
244		}
245	
246		private static boolean checkIterableForEach(MethodNode mth, LoopRegion loopRegion, IfCondition condition) {
247			List<RegisterArg> condArgs = condition.getRegisterArgs();
248			if (condArgs.size() != 1) {
249				return false;
250			}
251			RegisterArg iteratorArg = condArgs.get(0);
252			SSAVar sVar = iteratorArg.getSVar();
253			if (sVar == null || sVar.isUsedInPhi()) {
254				return false;
255			}
256			List<RegisterArg> itUseList = sVar.getUseList();
257			InsnNode assignInsn = iteratorArg.getAssignInsn();
258			if (itUseList.size() != 2) {
259				return false;
260			}
261			if (!checkInvoke(assignInsn, null, "iterator()Ljava/util/Iterator;")) {
262				return false;
263			}
264			InsnArg iterableArg = assignInsn.getArg(0);
265			InsnNode hasNextCall = itUseList.get(0).getParentInsn();
266			InsnNode nextCall = itUseList.get(1).getParentInsn();
267			if (!checkInvoke(hasNextCall, "java.util.Iterator", "hasNext()Z")
268					|| !checkInvoke(nextCall, "java.util.Iterator", "next()Ljava/lang/Object;")) {
269				return false;
270			}
271			List<InsnNode> toSkip = new ArrayList<>();
272			RegisterArg iterVar;
273			if (nextCall.contains(AFlag.WRAPPED)) {
274				InsnArg wrapArg = BlockUtils.searchWrappedInsnParent(mth, nextCall);
275				if (wrapArg != null && wrapArg.getParentInsn() != null) {
276					InsnNode parentInsn = wrapArg.getParentInsn();
277					BlockNode block = BlockUtils.getBlockByInsn(mth, parentInsn);
278					if (block == null) {
279						return false;
280					}
281					if (!RegionUtils.isRegionContainsBlock(loopRegion, block)) {
282						return false;
283					}
284					if (parentInsn.getType() == InsnType.CHECK_CAST) {
285						iterVar = parentInsn.getResult();
286						if (iterVar == null || !fixIterableType(mth, iterableArg, iterVar)) {
287							return false;
288						}
289						InsnArg castArg = BlockUtils.searchWrappedInsnParent(mth, parentInsn);
290						if (castArg != null && castArg.getParentInsn() != null) {
291							castArg.getParentInsn().replaceArg(castArg, iterVar);
292						} else {
293							// cast not inlined
294							toSkip.add(parentInsn);
295						}
296					} else {
297						iterVar = nextCall.getResult();
298						if (iterVar == null) {
299							return false;
300						}
301						iterVar.remove(AFlag.REMOVE); // restore variable from inlined insn
302						nextCall.add(AFlag.DONT_GENERATE);
303						if (!fixIterableType(mth, iterableArg, iterVar)) {
304							return false;
305						}
306						parentInsn.replaceArg(wrapArg, iterVar);
307					}
308				} else {
309					LOG.warn(" checkIterableForEach: Wrapped insn not found: {}, mth: {}", nextCall, mth);
310					return false;
311				}
312			} else {
313				iterVar = nextCall.getResult();
314				if (iterVar == null) {
315					return false;
316				}
317				if (!usedOnlyInLoop(mth, loopRegion, iterVar)) {
318					return false;
319				}
320				if (!assignOnlyInLoop(mth, loopRegion, iterVar)) {
321					return false;
322				}
323				toSkip.add(nextCall);
324			}
325	
326			assignInsn.add(AFlag.DONT_GENERATE);
327			assignInsn.getResult().add(AFlag.DONT_GENERATE);
328	
329			for (InsnNode insnNode : toSkip) {
330				insnNode.setResult(null);
331				insnNode.add(AFlag.DONT_GENERATE);
332			}
333			for (RegisterArg itArg : itUseList) {
334				itArg.add(AFlag.DONT_GENERATE);
335			}
336			ForEachLoop forEachLoop = new ForEachLoop(iterVar, iterableArg);
337			forEachLoop.injectFakeInsns(loopRegion);
338			loopRegion.setType(forEachLoop);
339			return true;
340		}
341	
342		private static boolean fixIterableType(MethodNode mth, InsnArg iterableArg, RegisterArg iterVar) {
343			ArgType iterableType = iterableArg.getType();
344			ArgType varType = iterVar.getType();
345			if (iterableType.isGeneric()) {
346				List<ArgType> genericTypes = iterableType.getGenericTypes();
347				if (genericTypes == null || genericTypes.size() != 1) {
348					return false;
349				}
350				ArgType gType = genericTypes.get(0);
351				if (gType.equals(varType)) {
352					return true;
353				}
354				if (gType.isGenericType()) {
355					iterVar.setType(gType);
356					return true;
357				}
358				if (ArgType.isInstanceOf(mth.root(), gType, varType)) {
359					return true;
360				}
361				ArgType wildcardType = gType.getWildcardType();
362				if (wildcardType != null
363						&& gType.getWildcardBound() == ArgType.WildcardBound.EXTENDS
364						&& ArgType.isInstanceOf(mth.root(), wildcardType, varType)) {
365					return true;
366				}
367				LOG.warn("Generic type differs: '{}' and '{}' in {}", gType, varType, mth);
368				return false;
369			}
370			if (!iterableArg.isRegister() || !iterableType.isObject()) {
371				return true;
372			}
373			ArgType genericType = ArgType.generic(iterableType.getObject(), varType);
374			if (iterableArg.isRegister()) {
375				ArgType immutableType = ((RegisterArg) iterableArg).getImmutableType();
376				if (immutableType != null && !immutableType.equals(genericType)) {
377					// can't change type
378					// allow to iterate over not generified collection only for Object vars
379					return varType.equals(ArgType.OBJECT);
380				}
381			}
382			iterableArg.setType(genericType);
383			return true;
384		}
385	
386		/**
387		 * Check if instruction is a interface invoke with corresponding parameters.
388		 */
389		private static boolean checkInvoke(InsnNode insn, String declClsFullName, String mthId) {
390			if (insn == null) {
391				return false;
392			}
393			if (insn.getType() == InsnType.INVOKE) {
394				InvokeNode inv = (InvokeNode) insn;
395				MethodInfo callMth = inv.getCallMth();
396				if ((inv.getInvokeType() == InvokeType.INTERFACE || inv.getInvokeType() == InvokeType.VIRTUAL)
397						&& callMth.getShortId().equals(mthId)) {
398					if (declClsFullName == null) {
399						return true;
400					}
401					return callMth.getDeclClass().getFullName().equals(declClsFullName);
402				}
403			}
404			return false;
405		}
406	
407		private static boolean assignOnlyInLoop(MethodNode mth, LoopRegion loopRegion, RegisterArg arg) {
408			InsnNode assignInsn = arg.getAssignInsn();
409			if (assignInsn == null) {
410				return true;
411			}
412			if (!argInLoop(mth, loopRegion, assignInsn.getResult())) {
413				return false;
414			}
415			if (assignInsn instanceof PhiInsn) {
416				PhiInsn phiInsn = (PhiInsn) assignInsn;
417				for (InsnArg phiArg : phiInsn.getArguments()) {
418					if (!assignOnlyInLoop(mth, loopRegion, (RegisterArg) phiArg)) {
419						return false;
420					}
421				}
422			}
423			return true;
424		}
425	
426		private static boolean usedOnlyInLoop(MethodNode mth, LoopRegion loopRegion, RegisterArg arg) {
427			List<RegisterArg> useList = arg.getSVar().getUseList();
428			for (RegisterArg useArg : useList) {
429				if (!argInLoop(mth, loopRegion, useArg)) {
430					return false;
431				}
432			}
433			return true;
434		}
435	
436		private static boolean argInLoop(MethodNode mth, LoopRegion loopRegion, RegisterArg arg) {
437			InsnNode parentInsn = arg.getParentInsn();
438			if (parentInsn == null) {
439				return false;
440			}
441			BlockNode block = BlockUtils.getBlockByInsn(mth, parentInsn);
442			if (block == null) {
443				LOG.debug(" LoopRegionVisitor: instruction not found: {}, mth: {}", parentInsn, mth);
444				return false;
445			}
446			return RegionUtils.isRegionContainsBlock(loopRegion, block);
447		}
