29	
30	public class RenameVisitor extends AbstractVisitor {
31		private static final Pattern ANONYMOUS_CLASS_PATTERN = Pattern.compile("^\\d+$");
32	
33		@Override
34		public void init(RootNode root) {
35			List<File> inputFiles = root.getArgs().getInputFiles();
36			if (inputFiles.isEmpty()) {
37				return;
38			}
39			process(root);
40			root.registerCodeDataUpdateListener(codeData -> process(root));
41		}
42	
43		private void process(RootNode root) {
44			UserRenames.apply(root);
45			checkNames(root);
46		}
47	
48		private static void checkNames(RootNode root) {
49			JadxArgs args = root.getArgs();
50			if (args.getRenameFlags().isEmpty()) {
51				return;
52			}
53	
54			IAliasProvider aliasProvider = args.getAliasProvider();
55	
56			List<ClassNode> classes = root.getClasses(true);
57			for (ClassNode cls : classes) {
58				checkClassName(aliasProvider, cls, args);
59				checkFields(aliasProvider, cls, args);
60				checkMethods(aliasProvider, cls, args);
61			}
62			boolean pkgUpdated = false;
63			for (PackageNode pkg : root.getPackages()) {
64				pkgUpdated |= checkPackage(args, aliasProvider, pkg);
65			}
66			if (!args.isFsCaseSensitive() && args.isRenameCaseSensitive()) {
67				// check for package directory conflicts on case insensitive filesystems
68				Set<String> pkgPaths = new HashSet<>();
69				for (PackageNode pkg : root.getPackages()) {
70					String pkgPath = pkg.getAliasPkgInfo().getFullName().toLowerCase();
71					if (!pkgPaths.add(pkgPath)) {
72						pkg.setLeafAlias(aliasProvider.forPackage(pkg), false);
73						pkgUpdated = true;
74						// verify the new name also doesn't conflict
75						if (!pkgPaths.add(pkg.getAliasPkgInfo().getFullName().toLowerCase())) {
76							pkg.setLeafAlias(aliasProvider.forPackage(pkg), false);
77						}
78					}
79				}
80			}
81			if (pkgUpdated) {
82				root.runPackagesUpdate();
83			}
84			if (!args.isFsCaseSensitive() && args.isRenameCaseSensitive()) {
85				// check for class file conflicts on case insensitive filesystems (run after package rename)
86				Set<String> clsFullPaths = new HashSet<>(classes.size());
87				for (ClassNode cls : classes) {
88					ClassInfo clsInfo = cls.getClassInfo();
89					if (!clsFullPaths.add(clsInfo.getAliasFullPath().toLowerCase())) {
90						clsInfo.changeShortName(aliasProvider.forClass(cls));
91						cls.addAttr(new RenameReasonAttr(cls).append("case insensitive filesystem"));
92						// verify the new name also doesn't conflict
93						if (!clsFullPaths.add(clsInfo.getAliasFullPath().toLowerCase())) {
94							clsInfo.changeShortName(aliasProvider.forClass(cls));
95						}
96					}
97				}
98			}
99			processRootPackages(aliasProvider, root, classes);
100		}
101	
102		private static void checkClassName(IAliasProvider aliasProvider, ClassNode cls, JadxArgs args) {
103			if (cls.contains(AFlag.DONT_RENAME)) {
104				return;
105			}
106			ClassInfo classInfo = cls.getClassInfo();
107			String clsName = classInfo.getAliasShortName();
108	
109			String newShortName = fixClsShortName(args, clsName);
110			if (newShortName == null) {
111				// rename failed, use deobfuscator
112				cls.rename(aliasProvider.forClass(cls));
113				cls.addAttr(new RenameReasonAttr(cls).notPrintable());
114				return;
115			}
116			if (!newShortName.equals(clsName)) {
117				classInfo.changeShortName(newShortName);
118				cls.addAttr(new RenameReasonAttr(cls).append("invalid class name"));
119			}
120			if (classInfo.isInner() && args.isRenameValid()) {
121				// check inner classes names
122				ClassInfo parentClass = classInfo.getParentClass();
123				while (parentClass != null) {
124					if (parentClass.getAliasShortName().equals(newShortName)) {
125						cls.rename(aliasProvider.forClass(cls));
126						cls.addAttr(new RenameReasonAttr(cls).append("collision with other inner class name"));
127						break;
128					}
129					parentClass = parentClass.getParentClass();
130				}
131			}
132		}
133	
134		private static boolean checkPackage(JadxArgs args, IAliasProvider aliasProvider, PackageNode pkg) {
135			if (args.isRenameValid() && pkg.getAliasPkgInfo().isDefaultPkg()) {
136				pkg.setFullAlias(Consts.DEFAULT_PACKAGE_NAME, false);
137				return true;
138			}
139			String pkgName = pkg.getAliasPkgInfo().getName();
140			boolean notValid = args.isRenameValid() && !NameMapper.isValidIdentifier(pkgName);
141			boolean notPrintable = args.isRenamePrintable() && !NameMapper.isAllCharsPrintable(pkgName);
142			if (notValid || notPrintable) {
143				pkg.setLeafAlias(aliasProvider.forPackage(pkg), false);
144				return true;
145			}
146			return false;
147		}
148	
149		@Nullable
150		private static String fixClsShortName(JadxArgs args, String clsName) {
151			if (StringUtils.isEmpty(clsName)) {
152				return null;
153			}
154			boolean renameValid = args.isRenameValid();
155			if (renameValid) {
156				if (ANONYMOUS_CLASS_PATTERN.matcher(clsName).matches()) {
157					return Consts.ANONYMOUS_CLASS_PREFIX + NameMapper.removeInvalidCharsMiddle(clsName);
158				}
159	
160				char firstChar = clsName.charAt(0);
161				if (firstChar == '$' || Character.isDigit(firstChar)) {
162					return 'C' + NameMapper.removeInvalidCharsMiddle(clsName);
163				}
164			}
165			String cleanClsName = args.isRenamePrintable()
166					? NameMapper.removeNonPrintableCharacters(clsName)
167					: clsName;
168			if (cleanClsName.isEmpty()) {
169				return null;
170			}
171			if (renameValid) {
172				cleanClsName = NameMapper.removeInvalidChars(clsName, "C");
173				if (!NameMapper.isValidIdentifier(cleanClsName)) {
174					return 'C' + cleanClsName;
175				}
176			}
177			return cleanClsName;
178		}
179	
180		private static void checkFields(IAliasProvider aliasProvider, ClassNode cls, JadxArgs args) {
181			Set<String> names = new HashSet<>();
182			for (FieldNode field : cls.getFields()) {
183				FieldInfo fieldInfo = field.getFieldInfo();
184				String fieldName = fieldInfo.getAlias();
185				boolean notUnique = !names.add(fieldName);
186				boolean notValid = args.isRenameValid() && !NameMapper.isValidIdentifier(fieldName);
187				boolean notPrintable = args.isRenamePrintable() && !NameMapper.isAllCharsPrintable(fieldName);
188				if (notUnique || notValid || notPrintable) {
189					field.rename(aliasProvider.forField(field));
190					field.addAttr(new RenameReasonAttr(field, notValid, notPrintable));
191					if (notUnique) {
192						field.addAttr(new RenameReasonAttr(field).append("collision with other field name"));
193					}
194				}
195			}
196		}
197	
198		private static void checkMethods(IAliasProvider aliasProvider, ClassNode cls, JadxArgs args) {
199			List<MethodNode> methods = new ArrayList<>(cls.getMethods().size());
200			for (MethodNode method : cls.getMethods()) {
201				if (!method.getAccessFlags().isConstructor()) {
202					methods.add(method);
203				}
204			}
205			for (MethodNode mth : methods) {
206				String alias = mth.getAlias();
207				boolean notValid = args.isRenameValid() && !NameMapper.isValidIdentifier(alias);
208				boolean notPrintable = args.isRenamePrintable() && !NameMapper.isAllCharsPrintable(alias);
209				if (notValid || notPrintable) {
210					mth.rename(aliasProvider.forMethod(mth));
211					mth.addAttr(new RenameReasonAttr(mth, notValid, notPrintable));
212				}
213			}
214			// Rename methods with same signature
215			if (args.isRenameValid()) {
216				Set<String> names = new HashSet<>(methods.size());
217				for (MethodNode mth : methods) {
218					String signature = mth.getMethodInfo().makeSignature(true, false);
219					if (!names.add(signature) && canRename(mth)) {
220						mth.rename(aliasProvider.forMethod(mth));
221						mth.addAttr(new RenameReasonAttr("collision with other method in class"));
222					}
223				}
224			}
225		}
226	
227		private static boolean canRename(MethodNode mth) {
228			if (mth.contains(AFlag.DONT_RENAME)) {
229				return false;
230			}
231			MethodOverrideAttr overrideAttr = mth.get(AType.METHOD_OVERRIDE);
232			if (overrideAttr != null) {
233				for (MethodNode relatedMth : overrideAttr.getRelatedMthNodes()) {
234					if (relatedMth != mth && mth.getParentClass().equals(relatedMth.getParentClass())) {
235						// ignore rename if exists related method from same class (bridge method in most cases)
236						// such rename will also rename current method and will not help to resolve name collision
237						return false;
238					}
239				}
240			}
241			return true;
242		}
243	
244		private static void processRootPackages(IAliasProvider aliasProvider, RootNode root, List<ClassNode> classes) {
245			Set<String> rootPkgs = collectRootPkgs(root);
246			root.getCacheStorage().setRootPkgs(rootPkgs);
247	
248			if (root.getArgs().isRenameValid()) {
249				// rename field if collide with any root package
250				for (ClassNode cls : classes) {
251					for (FieldNode field : cls.getFields()) {
252						if (rootPkgs.contains(field.getAlias())) {
253							field.rename(aliasProvider.forField(field));
254							field.addAttr(new RenameReasonAttr("collision with root package name"));
255						}
256					}
257				}
258			}
259		}
260	
261		private static Set<String> collectRootPkgs(RootNode root) {
262			Set<String> rootPkgs = new HashSet<>();
263			for (PackageNode pkg : root.getPackages()) {
264				if (pkg.isRoot()) {
265					rootPkgs.add(pkg.getPkgInfo().getName());
266				}
267			}
268			return rootPkgs;
269		}
270	
271		@Override
272		public String getName() {
273			return "RenameVisitor";
274		}
275	}
