83				code.startLine();
84				code.attachDefinition(mth);
85				code.add("static");
86				return true;
87			}
88			if (mth.contains(AFlag.ANONYMOUS_CONSTRUCTOR)) {
89				// don't add method name and arguments
90				code.startLine();
91				code.attachDefinition(mth);
92				return false;
93			}
94			if (Consts.DEBUG_USAGE) {
95				ClassGen.addMthUsageInfo(code, mth);
96			}
97			addOverrideAnnotation(code, mth);
98			annotationGen.addForMethod(code, mth);
