100			AccessInfo clsAccFlags = mth.getParentClass().getAccessFlags();

100			AccessInfo clsAccFlags = mth.getParentClass().getAccessFlags();
101			AccessInfo ai = mth.getAccessFlags();
102			// don't add 'abstract' and 'public' to methods in interface
103			if (clsAccFlags.isInterface()) {
104				ai = ai.remove(AccessFlags.ABSTRACT);
105				ai = ai.remove(AccessFlags.PUBLIC);
106			}
107			// don't add 'public' for annotations
108			if (clsAccFlags.isAnnotation()) {
109				ai = ai.remove(AccessFlags.PUBLIC);
110			}
111			if (mth.getMethodInfo().hasAlias() && !ai.isConstructor()) {
112				CodeGenUtils.addRenamedComment(code, mth, mth.getName());
113			}
