119					if (code.isMetadataSupported()) {
120						code.startLine("To view partially-correct code enable 'Show inconsistent code' option in preferences");
121					} else {
122						code.startLine("To view partially-correct add '--show-bad-code' argument");
123					}
124				}
125				code.decIndent();
126				code.startLine("*/");
127			}
128	
129			code.startLineWithNum(mth.getSourceLine());
130			code.add(ai.makeString(mth.checkCommentsLevel(CommentsLevel.INFO)));
131			if (clsAccFlags.isInterface() && !mth.isNoCode() && !mth.getAccessFlags().isStatic()) {
132				// add 'default' for method with code in interface
133				code.add("default ");
134			}
135	
136			if (classGen.addGenericTypeParameters(code, mth.getTypeParameters(), false)) {
137				code.add(' ');
138			}
139			if (ai.isConstructor()) {
140				code.attachDefinition(mth);
141				code.add(classGen.getClassNode().getShortName()); // constructor
142			} else {
143				classGen.useType(code, mth.getReturnType());
144				code.add(' ');
145				MethodNode defMth = getMethodForDefinition();
146				code.attachDefinition(defMth);
147				code.add(defMth.getAlias());
148			}
149			code.add('(');
150			addMethodArguments(code);
151			code.add(')');
152	
153			annotationGen.addThrows(mth, code);
154	
155			// add default value for annotation class
156			if (mth.getParentClass().getAccessFlags().isAnnotation()) {
157				EncodedValue def = annotationGen.getAnnotationDefaultValue(mth);
158				if (def != null) {
159					code.add(" default ");
160					annotationGen.encodeValue(mth.root(), code, def);
161				}
162			}
163			return true;
164		}
