193		private void addMethodArguments(ICodeWriter code) {
194			List<RegisterArg> args = mth.getArgRegs();
195			AnnotationMethodParamsAttr paramsAnnotation = mth.get(JadxAttrType.ANNOTATION_MTH_PARAMETERS);
196			int argNum = -1;
197			int lastArgNum = args.size() - 1;
198			boolean first = true;
199			for (RegisterArg mthArg : args) {
200				argNum++;
201				if (SkipMethodArgsAttr.isSkip(mth, argNum)) {
202					continue;
203				}
204				if (first) {
205					first = false;
206				} else {
207					code.add(", ");
208				}
209				SSAVar ssaVar = mthArg.getSVar();
210				CodeVar var;
211				if (ssaVar == null) {
212					// abstract or interface methods
213					var = CodeVar.fromMthArg(mthArg, classGen.isFallbackMode());
214				} else {
215					var = ssaVar.getCodeVar();
216				}
217	
218				// add argument annotation
219				if (paramsAnnotation != null) {
220					annotationGen.addForParameter(code, paramsAnnotation, argNum);
221				}
222				if (var.isFinal()) {
223					code.add("final ");
224				}
225				ArgType argType;
226				ArgType varType = var.getType();
227				if (varType == null || varType == ArgType.UNKNOWN) {
228					// occur on decompilation errors
229					argType = mthArg.getInitType();
230				} else {
231					argType = varType;
232				}
233				if (argNum == lastArgNum && mth.getAccessFlags().isVarArgs()) {
234					// change last array argument to varargs
235					if (argType.isArray()) {
236						ArgType elType = argType.getArrayElement();
237						classGen.useType(code, elType);
238						code.add("...");
239					} else {
240						mth.addWarnComment("Last argument in varargs method is not array: " + var);
241						classGen.useType(code, argType);
242					}
243				} else {
244					classGen.useType(code, argType);
245				}
246				code.add(' ');
247				String varName = nameGen.assignArg(var);
248				if (code.isMetadataSupported() && ssaVar != null /* for fallback mode */) {
249					code.attachDefinition(VarNode.get(mth, var));

250				}
251				code.add(varName);
252			}
253		}
