255		public void addInstructions(ICodeWriter code) throws CodegenException {
256			JadxArgs args = mth.root().getArgs();
257			DecompileModeOverrideAttr modeOverrideAttr = mth.getTopParentClass().get(AType.DECOMPILE_MODE_OVERRIDE);
258			DecompilationMode mode;
259			if (modeOverrideAttr != null) {
260				mode = modeOverrideAttr.getMode();
261			} else {
262				mode = args.getDecompilationMode();
263			}
264			switch (mode) {
265				case AUTO:
266					if (classGen.isFallbackMode() || mth.getRegion() == null) {
267						// TODO: try simple mode first
268						dumpInstructions(code);
269					} else {
270						addRegionInsns(code);
271					}
272					break;
273	
274				case RESTRUCTURE:
275					addRegionInsns(code);
276					break;
277	
278				case SIMPLE:
279					addSimpleMethodCode(code);
280					break;
281	
282				case FALLBACK:
283					addFallbackMethodCode(code, FALLBACK_MODE);
284					break;
285			}
286		}
