359		public void dumpInstructions(ICodeWriter code) {
360			if (mth.checkCommentsLevel(CommentsLevel.ERROR)) {
361				code.startLine("/*");
362				addFallbackMethodCode(code, COMMENTED_DUMP);
363				code.startLine("*/");
364			}
365			code.startLine("throw new UnsupportedOperationException(\"Method not decompiled: ")
366					.add(mth.getParentClass().getClassInfo().getAliasFullName())
367					.add('.')
368					.add(mth.getAlias())
369					.add('(')
370					.add(Utils.listToString(mth.getMethodInfo().getArgumentsTypes()))
371					.add("):")
372					.add(mth.getMethodInfo().getReturnType().toString())
373					.add("\");");
374		}
