112				CodeGenUtils.addRenamedComment(code, mth, mth.getName());
113			}
114			if (mth.contains(AFlag.INCONSISTENT_CODE) && mth.checkCommentsLevel(CommentsLevel.ERROR)) {
115				code.startLine("/*");
116				code.incIndent();
117				code.startLine("Code decompiled incorrectly, please refer to instructions dump.");
118				if (!mth.root().getArgs().isShowInconsistentCode()) {
119					if (code.isMetadataSupported()) {
