129			code.startLineWithNum(mth.getSourceLine());
130			code.add(ai.makeString(mth.checkCommentsLevel(CommentsLevel.INFO)));
131			if (clsAccFlags.isInterface() && !mth.isNoCode() && !mth.getAccessFlags().isStatic()) {
132				// add 'default' for method with code in interface
