288		public void addRegionInsns(ICodeWriter code) throws CodegenException {
289			try {
290				RegionGen regionGen = new RegionGen(this);
291				regionGen.makeRegion(code, mth.getRegion());
292			} catch (StackOverflowError | BootstrapMethodError e) {
293				mth.addError("Method code generation error", new JadxOverflowException("StackOverflow"));
294				CodeGenUtils.addErrors(code, mth);
295				dumpInstructions(code);
296			} catch (Exception e) {
297				if (mth.getParentClass().getTopParentClass().contains(AFlag.RESTART_CODEGEN)) {
298					throw e;
299				}
300				mth.addError("Method code generation error", e);
301				CodeGenUtils.addErrors(code, mth);
302				dumpInstructions(code);
303			}
304		}
