539		 * Return fallback variant of method codegen
540		 */
541		public static MethodGen getFallbackMethodGen(MethodNode mth) {
542			ClassGen clsGen = new ClassGen(mth.getParentClass(), null, false, true, true, IntegerFormat.AUTO);
543			return new MethodGen(clsGen, mth);
544		}
