550		public static String getLabelName(IfNode insn) {
551			BlockNode thenBlock = insn.getThenBlock();
552			if (thenBlock != null) {
553				return getLabelName(thenBlock);
554			}
555			return getLabelName(insn.getTarget());
556		}
