30	@JadxVisitor(
31			name = "CodeShrinkVisitor",
32			desc = "Inline variables to make code smaller",
33			runAfter = { ModVisitor.class }
34	)
35	public class CodeShrinkVisitor extends AbstractVisitor {
36	
37		@Override
38		public void visit(MethodNode mth) {
39			shrinkMethod(mth);
40		}
41	
42		public static void shrinkMethod(MethodNode mth) {
43			if (mth.isNoCode()) {
44				return;
45			}
46			mth.remove(AFlag.REQUEST_CODE_SHRINK);
47			for (BlockNode block : mth.getBasicBlocks()) {
48				shrinkBlock(mth, block);
49				simplifyMoveInsns(mth, block);
50			}
51		}
52	
53		private static void shrinkBlock(MethodNode mth, BlockNode block) {
54			if (block.getInstructions().isEmpty()) {
55				return;
56			}
57			InsnList insnList = new InsnList(block.getInstructions());
58			int insnCount = insnList.size();
59			List<ArgsInfo> argsList = new ArrayList<>(insnCount);
60			for (int i = 0; i < insnCount; i++) {
61				argsList.add(new ArgsInfo(insnList.get(i), argsList, i));
62			}
63			List<WrapInfo> wrapList = new ArrayList<>();
64			for (ArgsInfo argsInfo : argsList) {
65				List<RegisterArg> args = argsInfo.getArgs();
66				for (int i = args.size() - 1; i >= 0; i--) {
67					RegisterArg arg = args.get(i);
68					checkInline(mth, block, insnList, wrapList, argsInfo, arg);
69				}
70			}
71			if (!wrapList.isEmpty()) {
72				for (WrapInfo wrapInfo : wrapList) {
73					inline(mth, wrapInfo.getArg(), wrapInfo.getInsn(), block);
74				}
75			}
76		}
77	
78		private static void checkInline(MethodNode mth, BlockNode block, InsnList insnList,
79				List<WrapInfo> wrapList, ArgsInfo argsInfo, RegisterArg arg) {
80			if (arg.contains(AFlag.DONT_INLINE)
81					|| arg.getParentInsn() == null
82					|| arg.getParentInsn().contains(AFlag.DONT_GENERATE)) {
83				return;
84			}
85			SSAVar sVar = arg.getSVar();
86			if (sVar == null || sVar.getAssign().contains(AFlag.DONT_INLINE)) {
87				return;
88			}
89			InsnNode assignInsn = sVar.getAssign().getParentInsn();
90			if (assignInsn == null
91					|| assignInsn.contains(AFlag.DONT_INLINE)
92					|| assignInsn.contains(AFlag.WRAPPED)) {
93				return;
94			}
95			boolean assignInline = assignInsn.contains(AFlag.FORCE_ASSIGN_INLINE);
96			if (!assignInline && sVar.isUsedInPhi()) {
97				return;
98			}
99			// allow inline only one use arg
100			int useCount = 0;
101			for (RegisterArg useArg : sVar.getUseList()) {
102				InsnNode parentInsn = useArg.getParentInsn();
103				if (parentInsn != null && parentInsn.contains(AFlag.DONT_GENERATE)) {
104					continue;
105				}
106				if (!assignInline && useArg.contains(AFlag.DONT_INLINE_CONST)) {
107					return;
108				}
109				useCount++;
110			}
111			if (!assignInline && useCount != 1) {
112				return;
113			}
114			if (!assignInline && sVar.getName() != null) {
115				if (searchArgWithName(assignInsn, sVar.getName())) {
116					// allow inline if name is reused in result
117				} else if (varWithSameNameExists(mth, sVar)) {
118					// allow inline if var name is duplicated
119				} else {
120					// reject inline of named variable
121					return;
122				}
123			}
124			if (!checkLambdaInline(arg, assignInsn)) {
125				return;
126			}
127	
128			int assignPos = insnList.getIndex(assignInsn);
129			if (assignPos != -1) {
130				WrapInfo wrapInfo = argsInfo.checkInline(assignPos, arg);
131				if (wrapInfo != null) {
132					wrapList.add(wrapInfo);
133				}
134			} else {
135				// another block
136				BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
137				if (assignBlock != null
138						&& assignInsn != arg.getParentInsn()
139						&& canMoveBetweenBlocks(mth, assignInsn, assignBlock, block, argsInfo.getInsn())) {
140					if (assignInline) {
141						assignInline(mth, arg, assignInsn, assignBlock);
142					} else {
143						inline(mth, arg, assignInsn, assignBlock);
144					}
145				}
146			}
147		}
148	
149		/**
150		 * Forbid inline lambda into invoke as an instance arg, i.e. this will not compile:
151		 * {@code () -> { ... }.apply(); }
152		 */
153		private static boolean checkLambdaInline(RegisterArg arg, InsnNode assignInsn) {
154			if (assignInsn.getType() == InsnType.INVOKE && assignInsn instanceof InvokeCustomNode) {
155				for (RegisterArg useArg : arg.getSVar().getUseList()) {
156					InsnNode parentInsn = useArg.getParentInsn();
157					if (parentInsn != null && parentInsn.getType() == InsnType.INVOKE) {
158						InvokeNode invokeNode = (InvokeNode) parentInsn;
159						InsnArg instArg = invokeNode.getInstanceArg();
160						if (instArg != null && instArg == useArg) {
161							return false;
162						}
163					}
164				}
165			}
166			return true;
167		}
168	
169		private static boolean varWithSameNameExists(MethodNode mth, SSAVar inlineVar) {
170			for (SSAVar ssaVar : mth.getSVars()) {
171				if (ssaVar == inlineVar || ssaVar.getCodeVar() == inlineVar.getCodeVar()) {
172					continue;
173				}
174				if (Objects.equals(ssaVar.getName(), inlineVar.getName())) {
175					return ssaVar.getUseCount() > inlineVar.getUseCount();
176				}
177			}
178			return false;
179		}
180	
181		private static boolean searchArgWithName(InsnNode assignInsn, String varName) {
182			InsnArg result = assignInsn.visitArgs(insnArg -> {
183				if (insnArg instanceof Named) {
184					String argName = ((Named) insnArg).getName();
185					if (Objects.equals(argName, varName)) {
186						return insnArg;
187					}
188				}
189				return null;
190			});
191			return result != null;
192		}
193	
194		private static boolean assignInline(MethodNode mth, RegisterArg arg, InsnNode assignInsn, BlockNode assignBlock) {
195			RegisterArg useArg = arg.getSVar().getUseList().get(0);
196			InsnNode useInsn = useArg.getParentInsn();
197			if (useInsn == null || useInsn.contains(AFlag.DONT_GENERATE)) {
198				return false;
199			}
200			if (!InsnRemover.removeWithoutUnbind(mth, assignBlock, assignInsn)) {
201				return false;
202			}
203			useArg.wrapInstruction(mth, assignInsn);
204			return true;
205		}
206	
207		private static boolean inline(MethodNode mth, RegisterArg arg, InsnNode insn, BlockNode block) {
208			if (insn.contains(AFlag.FORCE_ASSIGN_INLINE)) {
209				return assignInline(mth, arg, insn, block);
210			}
211			// just move instruction into arg, don't unbind/copy/duplicate
212			InsnArg wrappedArg = arg.wrapInstruction(mth, insn, false);
213			boolean replaced = wrappedArg != null;
214			if (replaced) {
215				InsnNode parentInsn = arg.getParentInsn();
216				if (parentInsn != null) {
217					parentInsn.inheritMetadata(insn);
218				}
219				InsnRemover.unbindResult(mth, insn);
220				InsnRemover.removeWithoutUnbind(mth, block, insn);
221			}
222			return replaced;
223		}
224	
225		private static boolean canMoveBetweenBlocks(MethodNode mth, InsnNode assignInsn, BlockNode assignBlock,
226				BlockNode useBlock, InsnNode useInsn) {
227			if (!BlockUtils.isPathExists(assignBlock, useBlock)) {
228				return false;
229			}
230	
231			List<RegisterArg> argsList = ArgsInfo.getArgs(assignInsn);
232			BitSet args = new BitSet();
233			for (RegisterArg arg : argsList) {
234				args.set(arg.getRegNum());
235			}
236			boolean startCheck = false;
237			for (InsnNode insn : assignBlock.getInstructions()) {
238				if (startCheck && (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args))) {
239					return false;
240				}
241				if (insn == assignInsn) {
242					startCheck = true;
243				}
244			}
245			Set<BlockNode> pathsBlocks = BlockUtils.getAllPathsBlocks(assignBlock, useBlock);
246			pathsBlocks.remove(assignBlock);
247			pathsBlocks.remove(useBlock);
248			for (BlockNode block : pathsBlocks) {
249				if (block.contains(AFlag.DONT_GENERATE)) {
250					if (BlockUtils.checkLastInsnType(block, InsnType.MONITOR_EXIT)) {
251						if (RegionUtils.isBlocksInSameRegion(mth, assignBlock, useBlock)) {
252							// allow move inside same synchronized region
253						} else {
254							// don't move from synchronized block
255							return false;
256						}
257					}
258					// skip checks for not generated blocks
259					continue;
260				}
261				for (InsnNode insn : block.getInstructions()) {
262					if (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args)) {
263						return false;
264					}
265				}
266			}
267			for (InsnNode insn : useBlock.getInstructions()) {
268				if (insn == useInsn) {
269					return true;
270				}
271				if (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args)) {
272					return false;
273				}
274			}
275			throw new JadxRuntimeException("Can't process instruction move : " + assignBlock);
276		}
277	
278		private static void simplifyMoveInsns(MethodNode mth, BlockNode block) {
279			List<InsnNode> insns = block.getInstructions();
280			int size = insns.size();
281			for (int i = 0; i < size; i++) {
282				InsnNode insn = insns.get(i);
283				if (insn.getType() == InsnType.MOVE) {
284					// replace 'move' with wrapped insn
285					InsnArg arg = insn.getArg(0);
286					if (arg.isInsnWrap()) {
287						InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
288						InsnRemover.unbindResult(mth, wrapInsn);
289						wrapInsn.setResult(insn.getResult().duplicate());
290						wrapInsn.inheritMetadata(insn);
291						wrapInsn.setOffset(insn.getOffset());
292						wrapInsn.remove(AFlag.WRAPPED);
293						block.getInstructions().set(i, wrapInsn);
294					}
295				}
296			}
297		}
298	}
