56	public class RegionGen extends InsnGen {
57		private static final Logger LOG = LoggerFactory.getLogger(RegionGen.class);
58	
59		public RegionGen(MethodGen mgen) {
60			super(mgen, false);
61		}
62	
63		public void makeRegion(ICodeWriter code, IContainer cont) throws CodegenException {
64			declareVars(code, cont);
65			cont.generate(this, code);
66		}
67	
68		private void declareVars(ICodeWriter code, IContainer cont) {
69			DeclareVariablesAttr declVars = cont.get(AType.DECLARE_VARIABLES);
70			if (declVars != null) {
71				for (CodeVar v : declVars.getVars()) {
72					code.startLine();
73					declareVar(code, v);
74					code.add(';');
75					CodeGenUtils.addCodeComments(code, mth, v.getAnySsaVar().getAssign());
76				}
77			}
78		}
79	
80		private void makeRegionIndent(ICodeWriter code, IContainer region) throws CodegenException {
81			code.incIndent();
82			makeRegion(code, region);
83			code.decIndent();
84		}
85	
86		public void makeSimpleBlock(IBlock block, ICodeWriter code) throws CodegenException {
87			if (block.contains(AFlag.DONT_GENERATE)) {
88				return;
89			}
90	
91			for (InsnNode insn : block.getInstructions()) {
92				if (!insn.contains(AFlag.DONT_GENERATE)) {
93					makeInsn(insn, code);
94				}
95			}
96			ForceReturnAttr retAttr = block.get(AType.FORCE_RETURN);
97			if (retAttr != null) {
98				makeInsn(retAttr.getReturnInsn(), code);
99			}
100		}
101	
102		public void makeIf(IfRegion region, ICodeWriter code, boolean newLine) throws CodegenException {
103			if (newLine) {
104				code.startLineWithNum(region.getSourceLine());
105			} else {
106				code.attachSourceLine(region.getSourceLine());
107			}
108			boolean comment = region.contains(AFlag.COMMENT_OUT);
109			if (comment) {
110				code.add("// ");
111			}
112	
113			code.add("if (");
114			new ConditionGen(this).add(code, region.getCondition());
115			code.add(") {");
116			if (code.isMetadataSupported()) {
117				List<BlockNode> conditionBlocks = region.getConditionBlocks();
118				if (!conditionBlocks.isEmpty()) {
119					BlockNode blockNode = conditionBlocks.get(0);
120					InsnNode lastInsn = BlockUtils.getLastInsn(blockNode);
121					InsnCodeOffset.attach(code, lastInsn);
122					CodeGenUtils.addCodeComments(code, mth, lastInsn);
123				}
124			}
125			makeRegionIndent(code, region.getThenRegion());
126			if (comment) {
127				code.startLine("// }");
128			} else {
129				code.startLine('}');
130			}
131	
132			IContainer els = region.getElseRegion();
133			if (RegionUtils.notEmpty(els)) {
134				code.add(" else ");
135				if (connectElseIf(code, els)) {
136					return;
137				}
138				code.add('{');
139				makeRegionIndent(code, els);
140				if (comment) {
141					code.startLine("// }");
142				} else {
143					code.startLine('}');
144				}
145			}
146		}
147	
148		/**
149		 * Connect if-else-if block
150		 */
151		private boolean connectElseIf(ICodeWriter code, IContainer els) throws CodegenException {
152			if (els.contains(AFlag.ELSE_IF_CHAIN)) {
153				IContainer elseBlock = RegionUtils.getSingleSubBlock(els);
154				if (elseBlock instanceof IfRegion) {
155					declareVars(code, elseBlock);
156					makeIf((IfRegion) elseBlock, code, false);
157					return true;
158				}
159			}
160			return false;
161		}
162	
163		public void makeLoop(LoopRegion region, ICodeWriter code) throws CodegenException {
164			code.startLineWithNum(region.getSourceLine());
165			LoopLabelAttr labelAttr = region.getInfo().getStart().get(AType.LOOP_LABEL);
166			if (labelAttr != null) {
167				code.add(mgen.getNameGen().getLoopLabel(labelAttr)).add(": ");
168			}
169	
170			IfCondition condition = region.getCondition();
171			if (condition == null) {
172				// infinite loop
173				code.add("while (true) {");
174				makeRegionIndent(code, region.getBody());
175				code.startLine('}');
176				return;
177			}
178			InsnNode condInsn = condition.getFirstInsn();
179			InsnCodeOffset.attach(code, condInsn);
180	
181			ConditionGen conditionGen = new ConditionGen(this);
182			LoopType type = region.getType();
183			if (type != null) {
184				if (type instanceof ForLoop) {
185					ForLoop forLoop = (ForLoop) type;
186					code.add("for (");
187					makeInsn(forLoop.getInitInsn(), code, Flags.INLINE);
188					code.add("; ");
189					conditionGen.add(code, condition);
190					code.add("; ");
191					makeInsn(forLoop.getIncrInsn(), code, Flags.INLINE);
192					code.add(") {");
193					CodeGenUtils.addCodeComments(code, mth, condInsn);
194					makeRegionIndent(code, region.getBody());
195					code.startLine('}');
196					return;
197				}
198				if (type instanceof ForEachLoop) {
199					ForEachLoop forEachLoop = (ForEachLoop) type;
200					code.add("for (");
201					declareVar(code, forEachLoop.getVarArg());
202					code.add(" : ");
203					addArg(code, forEachLoop.getIterableArg(), false);
204					code.add(") {");
205					CodeGenUtils.addCodeComments(code, mth, condInsn);
206					makeRegionIndent(code, region.getBody());
207					code.startLine('}');
208					return;
209				}
210				throw new JadxRuntimeException("Unknown loop type: " + type.getClass());
211			}
212			if (region.isConditionAtEnd()) {
213				code.add("do {");
214				CodeGenUtils.addCodeComments(code, mth, condInsn);
215				makeRegionIndent(code, region.getBody());
216				code.startLineWithNum(region.getSourceLine());
217				code.add("} while (");
218				conditionGen.add(code, condition);
219				code.add(");");
220			} else {
221				code.add("while (");
222				conditionGen.add(code, condition);
223				code.add(") {");
224				CodeGenUtils.addCodeComments(code, mth, condInsn);
225				makeRegionIndent(code, region.getBody());
226				code.startLine('}');
227			}
228		}
229	
230		public void makeSynchronizedRegion(SynchronizedRegion cont, ICodeWriter code) throws CodegenException {
231			code.startLine("synchronized (");
232			InsnNode monitorEnterInsn = cont.getEnterInsn();
233			addArg(code, monitorEnterInsn.getArg(0));
234			code.add(") {");
235	
236			InsnCodeOffset.attach(code, monitorEnterInsn);
237			CodeGenUtils.addCodeComments(code, mth, monitorEnterInsn);
238	
239			makeRegionIndent(code, cont.getRegion());
240			code.startLine('}');
241		}
242	
243		public void makeSwitch(SwitchRegion sw, ICodeWriter code) throws CodegenException {
244			SwitchInsn insn = (SwitchInsn) BlockUtils.getLastInsn(sw.getHeader());
245			Objects.requireNonNull(insn, "Switch insn not found in header");
246			InsnArg arg = insn.getArg(0);
247			code.startLine("switch (");
248			addArg(code, arg, false);
249			code.add(") {");
250			InsnCodeOffset.attach(code, insn);
251			CodeGenUtils.addCodeComments(code, mth, insn);
252			code.incIndent();
253	
254			for (CaseInfo caseInfo : sw.getCases()) {
255				List<Object> keys = caseInfo.getKeys();
256				IContainer c = caseInfo.getContainer();
257				for (Object k : keys) {
258					if (k == SwitchRegion.DEFAULT_CASE_KEY) {
259						code.startLine("default:");
260					} else {
261						code.startLine("case ");
262						addCaseKey(code, arg, k);
263						code.add(':');
264					}
265				}
266				makeRegionIndent(code, c);
267			}
268			code.decIndent();
269			code.startLine('}');
270		}
271	
272		private void addCaseKey(ICodeWriter code, InsnArg arg, Object k) throws CodegenException {
273			if (k instanceof FieldNode) {
274				FieldNode fld = (FieldNode) k;
275				useField(code, fld.getFieldInfo(), fld);
276			} else if (k instanceof FieldInfo) {
277				useField(code, (FieldInfo) k, null);
278			} else if (k instanceof Integer) {
279				code.add(TypeGen.literalToString((Integer) k, arg.getType(), mth, fallback));
280			} else if (k instanceof String) {
281				code.add('\"').add((String) k).add('\"');
282			} else {
283				throw new JadxRuntimeException("Unexpected key in switch: " + (k != null ? k.getClass() : null));
284			}
285		}
286	
287		private void useField(ICodeWriter code, FieldInfo fldInfo, @Nullable FieldNode fld) throws CodegenException {
288			boolean isEnum;
289			if (fld != null) {
290				isEnum = fld.getParentClass().isEnum();
291			} else {
292				ClspClass clsDetails = root.getClsp().getClsDetails(fldInfo.getDeclClass().getType());
293				isEnum = clsDetails != null && clsDetails.hasAccFlag(AccessFlags.ENUM);
294			}
295			if (isEnum) {
296				if (fld != null) {
297					code.attachAnnotation(fld);
298				}
299				code.add(fldInfo.getAlias());
300				return;
301			}
302			staticField(code, fldInfo);
303			if (fld != null && mth.checkCommentsLevel(CommentsLevel.INFO)) {
304				// print original value, sometimes replaced with incorrect field
305				EncodedValue constVal = fld.get(JadxAttrType.CONSTANT_VALUE);
306				if (constVal != null && constVal.getValue() != null) {
307					code.add(" /* ").add(constVal.getValue().toString()).add(" */");
308				}
309			}
310		}
311	
312		public void makeTryCatch(TryCatchRegion region, ICodeWriter code) throws CodegenException {
313			code.startLine("try {");
314			makeRegionIndent(code, region.getTryRegion());
315			// TODO: move search of 'allHandler' to 'TryCatchRegion'
316			ExceptionHandler allHandler = null;
317			for (Map.Entry<ExceptionHandler, IContainer> entry : region.getCatchRegions().entrySet()) {
318				ExceptionHandler handler = entry.getKey();
319				if (handler.isCatchAll()) {
320					if (allHandler != null) {
321						LOG.warn("Several 'all' handlers in try/catch block in {}", mth);
322					}
323					allHandler = handler;
324				} else {
325					makeCatchBlock(code, handler);
326				}
327			}
328			if (allHandler != null) {
329				makeCatchBlock(code, allHandler);
330			}
331			IContainer finallyRegion = region.getFinallyRegion();
332			if (finallyRegion != null) {
333				code.startLine("} finally {");
334				makeRegionIndent(code, finallyRegion);
335			}
336			code.startLine('}');
337		}
338	
339		private void makeCatchBlock(ICodeWriter code, ExceptionHandler handler) throws CodegenException {
340			IContainer region = handler.getHandlerRegion();
341			if (region == null) {
342				return;
343			}
344			code.startLine("} catch (");
345			if (handler.isCatchAll()) {
346				useClass(code, ArgType.THROWABLE);
347			} else {
348				Iterator<ClassInfo> it = handler.getCatchTypes().iterator();
349				if (it.hasNext()) {
350					useClass(code, it.next());
351				}
352				while (it.hasNext()) {
353					code.add(" | ");
354					useClass(code, it.next());
355				}
356			}
357			code.add(' ');
358			InsnArg arg = handler.getArg();
359			if (arg == null) {
360				code.add("unknown"); // throwing exception is too late at this point
361			} else if (arg instanceof RegisterArg) {
362				SSAVar ssaVar = ((RegisterArg) arg).getSVar();
363				if (code.isMetadataSupported()) {
364					code.attachDefinition(VarNode.get(mth, ssaVar));
365				}
366				code.add(mgen.getNameGen().assignArg(ssaVar.getCodeVar()));
367			} else if (arg instanceof NamedArg) {
368				code.add(mgen.getNameGen().assignNamedArg((NamedArg) arg));
369			} else {
370				throw new JadxRuntimeException("Unexpected arg type in catch block: " + arg + ", class: " + arg.getClass().getSimpleName());
371			}
372			code.add(") {");
373	
374			InsnCodeOffset.attach(code, handler.getHandlerOffset());
375			CodeGenUtils.addCodeComments(code, mth, handler.getHandlerBlock());
376	
377			makeRegionIndent(code, region);
378		}
379	}
