1	package jadx.core.dex.visitors.regions;
2	
3	import java.util.List;
4	
5	import jadx.core.dex.attributes.AFlag;
6	import jadx.core.dex.instructions.InsnType;
7	import jadx.core.dex.nodes.IContainer;
8	import jadx.core.dex.nodes.IRegion;
9	import jadx.core.dex.nodes.InsnNode;
10	import jadx.core.dex.nodes.MethodNode;
11	import jadx.core.dex.regions.Region;
12	import jadx.core.dex.regions.conditions.IfCondition;
13	import jadx.core.dex.regions.conditions.IfCondition.Mode;
14	import jadx.core.dex.regions.conditions.IfRegion;
15	import jadx.core.dex.visitors.AbstractVisitor;
16	import jadx.core.utils.InsnUtils;
17	import jadx.core.utils.RegionUtils;
18	
19	import static jadx.core.utils.RegionUtils.insnsCount;
20	
21	public class IfRegionVisitor extends AbstractVisitor {
22		private static final ProcessIfRegionVisitor PROCESS_IF_REGION_VISITOR = new ProcessIfRegionVisitor();
23		private static final RemoveRedundantElseVisitor REMOVE_REDUNDANT_ELSE_VISITOR = new RemoveRedundantElseVisitor();
24	
25		@Override
26		public void visit(MethodNode mth) {
27			if (mth.isNoCode()) {
28				return;
29			}
30			process(mth);
31		}
32	
33		public static void processIfRequested(MethodNode mth) {
34			if (mth.contains(AFlag.REQUEST_IF_REGION_OPTIMIZE)) {
35				try {
36					process(mth);
37				} finally {
38					mth.remove(AFlag.REQUEST_IF_REGION_OPTIMIZE);
39				}
40			}
41		}
42	
43		private static void process(MethodNode mth) {
44			TernaryMod.process(mth);
45			DepthRegionTraversal.traverse(mth, PROCESS_IF_REGION_VISITOR);
46			DepthRegionTraversal.traverseIterative(mth, REMOVE_REDUNDANT_ELSE_VISITOR);
47		}
48	
49		private static class ProcessIfRegionVisitor extends AbstractRegionVisitor {
50			@Override
51			public boolean enterRegion(MethodNode mth, IRegion region) {
52				if (region instanceof IfRegion) {
53					IfRegion ifRegion = (IfRegion) region;
54					orderBranches(mth, ifRegion);
55					markElseIfChains(mth, ifRegion);
56				}
57				return true;
58			}
59		}
60	
61		@SuppressWarnings({ "UnnecessaryReturnStatement" })
62		private static void orderBranches(MethodNode mth, IfRegion ifRegion) {
63			if (RegionUtils.isEmpty(ifRegion.getElseRegion())) {
64				return;
65			}
66			if (RegionUtils.isEmpty(ifRegion.getThenRegion())) {
67				invertIfRegion(ifRegion);
68				return;
69			}
70			if (mth.contains(AFlag.USE_LINES_HINTS)) {
71				int thenLine = RegionUtils.getFirstSourceLine(ifRegion.getThenRegion());
72				int elseLine = RegionUtils.getFirstSourceLine(ifRegion.getElseRegion());
73				if (thenLine != 0 && elseLine != 0) {
74					if (thenLine > elseLine) {
75						invertIfRegion(ifRegion);
76					}
77					return;
78				}
79			}
80			if (ifRegion.simplifyCondition()) {
81				IfCondition condition = ifRegion.getCondition();
82				if (condition != null && condition.getMode() == Mode.NOT) {
83					invertIfRegion(ifRegion);
84				}
85			}
86			int thenSize = insnsCount(ifRegion.getThenRegion());
87			int elseSize = insnsCount(ifRegion.getElseRegion());
88			if (isSimpleExitBlock(mth, ifRegion.getElseRegion())) {
89				if (isSimpleExitBlock(mth, ifRegion.getThenRegion())) {
90					if (elseSize < thenSize) {
91						invertIfRegion(ifRegion);
92						return;
93					}
94				}
95				if (elseSize == 1) {
96					boolean lastRegion = RegionUtils.hasExitEdge(ifRegion);
97					if (lastRegion && mth.isVoidReturn()) {
98						InsnNode lastElseInsn = RegionUtils.getLastInsn(ifRegion.getElseRegion());
99						if (InsnUtils.isInsnType(lastElseInsn, InsnType.THROW)) {
100							// move `throw` into `then` block
101							invertIfRegion(ifRegion);
102						} else {
103							// single return at method end will be removed later
104						}
105						return;
106					}
107					if (thenSize > 2 && !(lastRegion && thenSize < 4 /* keep small code block inside else */)) {
108						invertIfRegion(ifRegion);
109						return;
110					}
111				}
112			}
113			boolean thenExit = RegionUtils.hasExitBlock(ifRegion.getThenRegion());
114			boolean elseExit = RegionUtils.hasExitBlock(ifRegion.getElseRegion());
115			if (elseExit && (!thenExit || elseSize < thenSize)) {
116				invertIfRegion(ifRegion);
117				return;
118			}
119			// move 'if' from 'then' branch to make 'else if' chain
120			if (isIfRegion(ifRegion.getThenRegion())
121					&& !isIfRegion(ifRegion.getElseRegion())
122					&& !thenExit) {
123				invertIfRegion(ifRegion);
124				return;
125			}
126			// move 'break' into 'then' branch
127			if (RegionUtils.hasBreakInsn(ifRegion.getElseRegion())) {
128				invertIfRegion(ifRegion);
129				return;
130			}
131		}
132	
133		private static boolean isIfRegion(IContainer container) {
134			if (container instanceof IfRegion) {
135				return true;
136			}
137			if (container instanceof IRegion) {
138				List<IContainer> subBlocks = ((IRegion) container).getSubBlocks();
139				return subBlocks.size() == 1 && subBlocks.get(0) instanceof IfRegion;
140			}
141			return false;
142		}
143	
144		/**
145		 * Mark if-else-if chains
146		 */
147		private static void markElseIfChains(MethodNode mth, IfRegion ifRegion) {
148			if (isSimpleExitBlock(mth, ifRegion.getThenRegion())) {
149				return;
150			}
151			IContainer elsRegion = ifRegion.getElseRegion();
152			if (elsRegion instanceof Region) {
153				List<IContainer> subBlocks = ((Region) elsRegion).getSubBlocks();
154				if (subBlocks.size() == 1 && subBlocks.get(0) instanceof IfRegion) {
155					subBlocks.get(0).add(AFlag.ELSE_IF_CHAIN);
156					elsRegion.add(AFlag.ELSE_IF_CHAIN);
157				}
158			}
159		}
160	
161		private static class RemoveRedundantElseVisitor implements IRegionIterativeVisitor {
162			@Override
163			public boolean visitRegion(MethodNode mth, IRegion region) {
164				if (region instanceof IfRegion) {
165					return removeRedundantElseBlock(mth, (IfRegion) region);
166				}
167				return false;
168			}
169		}
170	
171		@SuppressWarnings("UnnecessaryParentheses")
172		private static boolean removeRedundantElseBlock(MethodNode mth, IfRegion ifRegion) {
173			if (ifRegion.getElseRegion() == null) {
174				return false;
175			}
176			if (!RegionUtils.hasExitBlock(ifRegion.getThenRegion())) {
177				return false;
178			}
179			InsnNode lastThanInsn = RegionUtils.getLastInsn(ifRegion.getThenRegion());
180			if (InsnUtils.isInsnType(lastThanInsn, InsnType.THROW)) {
181				// always omit else after 'throw'
182			} else {
183				// code style check:
184				// will remove 'return;' from 'then' and 'else' with one instruction
185				// see #jadx.tests.integration.conditions.TestConditions9
186				if (mth.isVoidReturn()) {
187					int thenSize = insnsCount(ifRegion.getThenRegion());
188					// keep small blocks with same or 'similar' size unchanged
189					if (thenSize < 5) {
190						int elseSize = insnsCount(ifRegion.getElseRegion());
191						int range = ifRegion.getElseRegion().contains(AFlag.ELSE_IF_CHAIN) ? 4 : 2;
192						if (thenSize == elseSize || (thenSize * range > elseSize && thenSize < elseSize * range)) {
193							return false;
194						}
195					}
196				}
197			}
198			IRegion parent = ifRegion.getParent();
199			Region newRegion = new Region(parent);
200			if (parent.replaceSubBlock(ifRegion, newRegion)) {
201				newRegion.add(ifRegion);
202				newRegion.add(ifRegion.getElseRegion());
203				ifRegion.setElseRegion(null);
204				return true;
205			}
206			return false;
207		}
208	
209		private static void invertIfRegion(IfRegion ifRegion) {
210			IContainer elseRegion = ifRegion.getElseRegion();
211			if (elseRegion != null) {
212				ifRegion.invert();
213			}
214		}
215	
216		private static boolean isSimpleExitBlock(MethodNode mth, IContainer container) {
217			if (container == null) {
218				return false;
219			}
220			if (container.contains(AFlag.RETURN) || RegionUtils.isExitBlock(mth, container)) {
221				return true;
222			}
223			if (container instanceof IRegion) {
224				List<IContainer> subBlocks = ((IRegion) container).getSubBlocks();
225				return subBlocks.size() == 1 && RegionUtils.isExitBlock(mth, subBlocks.get(0));
226			}
227			return false;
228		}
229	}
