106			return declClass.getFullName() + '.' + name;
107		}
108	
109		public String getAliasFullName() {
110			return declClass.getAliasFullName() + '.' + alias;
111		}
112	
113		public String getFullId() {
114			return declClass.getFullName() + '.' + shortId;
115		}
116	
117		public String getRawFullId() {
118			return rawFullId;
119		}
120	
121		/**
122		 * Method name and signature
123		 */
124		public String getShortId() {
125			return shortId;
126		}
127	
128		public ClassInfo getDeclClass() {
129			return declClass;
130		}
131	
132		public ArgType getReturnType() {
133			return retType;
134		}
135	
136		public List<ArgType> getArgumentsTypes() {
137			return argTypes;
138		}
139	
140		public int getArgsCount() {
141			return argTypes.size();
142		}
143	
144		public boolean isConstructor() {
145			return name.equals("<init>");
146		}
147	
148		public boolean isClassInit() {
149			return name.equals("<clinit>");
150		}
151	
152		public String getAlias() {
153			return alias;
154		}
155	
156		public void setAlias(String alias) {
157			this.alias = alias;
158		}
159	
160		public void removeAlias() {
161			this.alias = name;
162		}
163	
164		public boolean hasAlias() {
165			return !name.equals(alias);
166		}
167	
168		public int calcHashCode() {
169			return shortId.hashCode() + 31 * declClass.hashCode();
170		}
171	
172		@Override
173		public int hashCode() {
174			return hash;
175		}
176	
177		@Override
178		public boolean equals(Object obj) {
179			if (this == obj) {
180				return true;
181			}
182			if (!(obj instanceof MethodInfo)) {
183				return false;
184			}
185			MethodInfo other = (MethodInfo) obj;
186			return shortId.equals(other.shortId)
187					&& declClass.equals(other.declClass);
188		}
189	
190		@Override
191		public int compareTo(MethodInfo other) {
192			int clsCmp = declClass.compareTo(other.declClass);
193			if (clsCmp != 0) {
194				return clsCmp;
195			}
196			return shortId.compareTo(other.shortId);
197		}
198	
199		@Override
200		public String toString() {
201			return declClass.getFullName() + '.' + name
202					+ '(' + Utils.listToString(argTypes) + "):" + retType;
203		}
204	}
