115		}
116	
117		public String getRawFullId() {
118			return rawFullId;
119		}
120	
121		/**
122		 * Method name and signature
123		 */
124		public String getShortId() {
125			return shortId;
126		}
127	
128		public ClassInfo getDeclClass() {
129			return declClass;
130		}
131	
132		public ArgType getReturnType() {
133			return retType;
134		}
135	
136		public List<ArgType> getArgumentsTypes() {
137			return argTypes;
138		}
139	
140		public int getArgsCount() {
141			return argTypes.size();
142		}
143	
144		public boolean isConstructor() {
