174		private void addOverrideAnnotation(ICodeWriter code, MethodNode mth) {
175			MethodOverrideAttr overrideAttr = mth.get(AType.METHOD_OVERRIDE);
176			if (overrideAttr == null) {
177				return;
178			}
179			if (!overrideAttr.getBaseMethods().contains(mth)) {
180				code.startLine("@Override");
181				if (mth.checkCommentsLevel(CommentsLevel.INFO)) {
182					code.add(" // ");
183					code.add(Utils.listToString(overrideAttr.getOverrideList(), ", ",
184							md -> md.getMethodInfo().getDeclClass().getAliasFullName()));
185				}
186			}
187			if (Consts.DEBUG) {
188				code.startLine("// related by override: ");
189				code.add(Utils.listToString(overrideAttr.getRelatedMthNodes(), ", ", m -> m.getParentClass().getFullName()));
190			}
191		}
