306		private void addSimpleMethodCode(ICodeWriter code) {
307			if (mth.getBasicBlocks() == null) {
308				code.startLine("// Blocks not ready for simple mode, using fallback");
309				addFallbackMethodCode(code, FALLBACK_MODE);
310				return;
311			}
312			JadxArgs args = mth.root().getArgs();
313			ICodeWriter tmpCode = args.getCodeWriterProvider().apply(args);
314			try {
315				tmpCode.setIndent(code.getIndent());
316				generateSimpleCode(tmpCode);
317				code.add(tmpCode);
318			} catch (Exception e) {
319				mth.addError("Simple mode code generation failed", e);
320				CodeGenUtils.addError(code, "Simple mode code generation failed", e);
321				dumpInstructions(code);
322			}
323		}
324	
325		private void generateSimpleCode(ICodeWriter code) throws CodegenException {
326			SimpleModeHelper helper = new SimpleModeHelper(mth);
327			List<BlockNode> blocks = helper.prepareBlocks();
328			InsnGen insnGen = new InsnGen(this, true);
329			for (BlockNode block : blocks) {
330				if (block.contains(AFlag.DONT_GENERATE)) {
331					continue;
332				}
333				if (helper.isNeedStartLabel(block)) {
334					code.decIndent();
335					code.startLine(getLabelName(block)).add(':');
336					code.incIndent();
337				}
338				for (InsnNode insn : block.getInstructions()) {
339					if (!insn.contains(AFlag.DONT_GENERATE)) {
340						if (insn.getResult() != null) {
341							CodeVar codeVar = insn.getResult().getSVar().getCodeVar();
342							if (!codeVar.isDeclared()) {
343								insn.add(AFlag.DECLARE_VAR);
344								codeVar.setDeclared(true);
345							}
346						}
347						InsnCodeOffset.attach(code, insn);
348						insnGen.makeInsn(insn, code);
349						addCatchComment(code, insn, false);
350						CodeGenUtils.addCodeComments(code, mth, insn);
351					}
352				}
353				if (helper.isNeedEndGoto(block)) {
354					code.startLine("goto ").add(getLabelName(block.getSuccessors().get(0)));
355				}
356			}
357		}
