359		public void dumpInstructions(ICodeWriter code) {
360			if (mth.checkCommentsLevel(CommentsLevel.ERROR)) {
361				code.startLine("/*");
362				addFallbackMethodCode(code, COMMENTED_DUMP);
363				code.startLine("*/");
364			}
365			code.startLine("throw new UnsupportedOperationException(\"Method not decompiled: ")
366					.add(mth.getParentClass().getClassInfo().getAliasFullName())
367					.add('.')
368					.add(mth.getAlias())
369					.add('(')
370					.add(Utils.listToString(mth.getMethodInfo().getArgumentsTypes()))
371					.add("):")
372					.add(mth.getMethodInfo().getReturnType().toString())
373					.add("\");");
374		}
375	
376		public void addFallbackMethodCode(ICodeWriter code, FallbackOption fallbackOption) {
377			if (fallbackOption == COMMENTED_DUMP && mth.getCommentsLevel() != CommentsLevel.DEBUG) {
378				long insnCountEstimate = mth.getInsnsCount();
379				if (insnCountEstimate > 200) {
380					code.incIndent();
381					code.startLine("Method dump skipped, instruction units count: " + insnCountEstimate);
382					if (code.isMetadataSupported()) {
383						code.startLine("To view this dump change 'Code comments level' option to 'DEBUG'");
384					} else {
385						code.startLine("To view this dump add '--comments-level debug' option");
386					}
387					code.decIndent();
388					return;
389				}
390			}
391			if (fallbackOption != FALLBACK_MODE) {
392				List<JadxError> errors = mth.getAll(AType.JADX_ERROR); // preserve error before unload
393				try {
394					// load original instructions
395					mth.unload();
396					mth.load();
397					for (IDexTreeVisitor visitor : Jadx.getFallbackPassesList()) {
398						DepthTraversal.visit(visitor, mth);
399					}
400				} catch (Exception e) {
401					LOG.error("Error reload instructions in fallback mode:", e);
402					code.startLine("// Can't load method instructions: " + e.getMessage());
403					return;
404				} finally {
405					mth.addAttr(AType.JADX_ERROR, errors);
406				}
407			}
408			InsnNode[] insnArr = mth.getInstructions();
409			if (insnArr == null) {
410				code.startLine("// Can't load method instructions.");
411				return;
412			}
413			code.incIndent();
414			if (mth.getThisArg() != null) {
415				code.startLine(nameGen.useArg(mth.getThisArg())).add(" = this;");
416			}
417			addFallbackInsns(code, mth, insnArr, fallbackOption);
418			code.decIndent();
419		}
420	
421		public enum FallbackOption {
422			FALLBACK_MODE,
423			BLOCK_DUMP,
424			COMMENTED_DUMP
425		}
426	
427		public static void addFallbackInsns(ICodeWriter code, MethodNode mth, InsnNode[] insnArr, FallbackOption option) {
428			int startIndent = code.getIndent();
429			MethodGen methodGen = getFallbackMethodGen(mth);
430			InsnGen insnGen = new InsnGen(methodGen, true);
431			InsnNode prevInsn = null;
432			for (InsnNode insn : insnArr) {
433				if (insn == null) {
434					continue;
435				}
436				methodGen.dumpInsn(code, insnGen, option, startIndent, prevInsn, insn);
437				prevInsn = insn;
438			}
439		}

440	
441		private boolean dumpInsn(ICodeWriter code, InsnGen insnGen, FallbackOption option, int startIndent,
442				@Nullable InsnNode prevInsn, InsnNode insn) {
443			if (insn.contains(AType.JADX_ERROR)) {
444				for (JadxError error : insn.getAll(AType.JADX_ERROR)) {
445					code.startLine("// ").add(error.getError());
446				}
447				return true;
448			}
449			if (option != BLOCK_DUMP && needLabel(insn, prevInsn)) {
450				code.decIndent();
451				code.startLine(getLabelName(insn.getOffset()) + ':');
452				code.incIndent();
453			}
454			if (insn.getType() == InsnType.NOP) {
455				return true;
456			}
457			try {
458				boolean escapeComment = isCommentEscapeNeeded(insn, option);
459				if (escapeComment) {
460					code.decIndent();
461					code.startLine("*/");
462					code.startLine("//  ");
463				} else {
464					code.startLineWithNum(insn.getSourceLine());
465				}
466				InsnCodeOffset.attach(code, insn);
467				RegisterArg resArg = insn.getResult();
468				if (resArg != null) {
469					ArgType varType = resArg.getInitType();
470					if (varType.isTypeKnown()) {
471						code.add(varType.toString()).add(' ');
472					}
473				}
474				insnGen.makeInsn(insn, code, InsnGen.Flags.INLINE);
475				if (escapeComment) {
476					code.startLine("/*");
477					code.incIndent();
478				}
479				addCatchComment(code, insn, true);
480				CodeGenUtils.addCodeComments(code, mth, insn);
481			} catch (Exception e) {
482				LOG.debug("Error generate fallback instruction: ", e.getCause());
483				code.setIndent(startIndent);
484				code.startLine("// error: " + insn);
485			}
486			return false;
487		}
488	
489		private void addCatchComment(ICodeWriter code, InsnNode insn, boolean raw) {
490			CatchAttr catchAttr = insn.get(AType.EXC_CATCH);
491			if (catchAttr == null) {
492				return;
493			}
494			code.add("     // Catch:");
495			for (ExceptionHandler handler : catchAttr.getHandlers()) {
496				code.add(' ');
497				classGen.useClass(code, handler.getArgType());
498				code.add(" -> ");
499				if (raw) {
500					code.add(getLabelName(handler.getHandlerOffset()));
501				} else {
502					code.add(getLabelName(handler.getHandlerBlock()));
503				}
504			}
505		}
506	
507		private static boolean isCommentEscapeNeeded(InsnNode insn, FallbackOption option) {
508			if (option == COMMENTED_DUMP) {
509				if (insn.getType() == InsnType.CONST_STR) {
510					String str = ((ConstStringNode) insn).getString();
511					return str.contains("*/");
512				}
513			}
514			return false;
515		}
516	
517		private static boolean needLabel(InsnNode insn, InsnNode prevInsn) {
518			if (insn.contains(AType.EXC_HANDLER)) {
519				return true;
520			}
521			if (insn.contains(AType.JUMP)) {
