216		private static boolean isSimpleExitBlock(MethodNode mth, IContainer container) {
217			if (container == null) {
218				return false;
219			}
220			if (container.contains(AFlag.RETURN) || RegionUtils.isExitBlock(mth, container)) {
221				return true;
222			}
223			if (container instanceof IRegion) {
224				List<IContainer> subBlocks = ((IRegion) container).getSubBlocks();
225				return subBlocks.size() == 1 && RegionUtils.isExitBlock(mth, subBlocks.get(0));
226			}
227			return false;
