173				code.add("while (true) {");
174				makeRegionIndent(code, region.getBody());
175				code.startLine('}');
176				return;
177			}
178			InsnNode condInsn = condition.getFirstInsn();
179			InsnCodeOffset.attach(code, condInsn);
180	
181			ConditionGen conditionGen = new ConditionGen(this);
182			LoopType type = region.getType();
183			if (type != null) {
184				if (type instanceof ForLoop) {
185					ForLoop forLoop = (ForLoop) type;
186					code.add("for (");
187					makeInsn(forLoop.getInitInsn(), code, Flags.INLINE);
188					code.add("; ");
189					conditionGen.add(code, condition);
190					code.add("; ");
191					makeInsn(forLoop.getIncrInsn(), code, Flags.INLINE);
192					code.add(") {");
193					CodeGenUtils.addCodeComments(code, mth, condInsn);
194					makeRegionIndent(code, region.getBody());
195					code.startLine('}');
196					return;
197				}
198				if (type instanceof ForEachLoop) {
199					ForEachLoop forEachLoop = (ForEachLoop) type;
200					code.add("for (");
201					declareVar(code, forEachLoop.getVarArg());
202					code.add(" : ");
203					addArg(code, forEachLoop.getIterableArg(), false);
204					code.add(") {");
205					CodeGenUtils.addCodeComments(code, mth, condInsn);
206					makeRegionIndent(code, region.getBody());
207					code.startLine('}');
208					return;
209				}
210				throw new JadxRuntimeException("Unknown loop type: " + type.getClass());
211			}
212			if (region.isConditionAtEnd()) {
213				code.add("do {");
214				CodeGenUtils.addCodeComments(code, mth, condInsn);
215				makeRegionIndent(code, region.getBody());
216				code.startLineWithNum(region.getSourceLine());
217				code.add("} while (");
218				conditionGen.add(code, condition);
219				code.add(");");

200			}
201			if (badElse) {
202				info = new IfInfo(info, thenBlock, null);
203				info.setOutBlock(elseBlock);
204			} else if (badThen) {
205				info = IfInfo.invert(info);
206				info = new IfInfo(info, elseBlock, null);
207				info.setOutBlock(thenBlock);
208			}
209	
210			// getPathCross may not find outBlock (e.g. one branch has return, outBlock definitely is
211			// null), so should check further
212			if (info.getOutBlock() == null) {
213				BlockNode scopeOutBlockThen = findScopeOutBlock(info.getThenBlock());
214				BlockNode scopeOutBlockElse = findScopeOutBlock(info.getElseBlock());
215				if (scopeOutBlockThen == null && scopeOutBlockElse != null) {
216					info.setOutBlock(scopeOutBlockElse);
217				} else if (scopeOutBlockThen != null && scopeOutBlockElse == null) {
218					info.setOutBlock(scopeOutBlockThen);
219				} else if (scopeOutBlockThen != null && scopeOutBlockThen == scopeOutBlockElse) {
220					info.setOutBlock(scopeOutBlockThen);
221				}
222			}
223	
224			if (BlockUtils.isBackEdge(block, info.getOutBlock())) {
225				info.setOutBlock(null);
226			}
227			return info;
228		}
