230		static @Nullable BlockNode findOutBlock(MethodNode mth, BlockNode thenBlock, BlockNode elseBlock) {
231			if (thenBlock == elseBlock) {
232				return thenBlock;
233			}
234			if (thenBlock == null || elseBlock == null) {
235				return null;
236			}
237	
238			BitSet thenDomFrontier = newBlocksBitSet(mth);
239			thenDomFrontier.or(thenBlock.getDomFrontier());
240			thenDomFrontier.set(thenBlock.getPos());
241	
242			BitSet elseDomFrontier = newBlocksBitSet(mth);
243			elseDomFrontier.or(elseBlock.getDomFrontier());
244			elseDomFrontier.set(elseBlock.getPos());
245	
246			BitSet intersection = newBlocksBitSet(mth);
247			intersection.or(thenDomFrontier);
248			intersection.and(elseDomFrontier);
249	
250			intersection.clear(mth.getExitBlock().getPos());
251			BlockNode oneBlock = bitSetToOneBlock(mth, intersection);
252	
253			// Attempt one: there's a unique block in the intersection of dom frontiers, and no path from
254			// then->else or else->then
255			if (oneBlock != null) {
256				return oneBlock;
257			}
258	
259			BitSet union = newBlocksBitSet(mth);
260			union.or(thenBlock.getDomFrontier());
261			union.or(elseBlock.getDomFrontier());
262			union.clear(mth.getExitBlock().getPos());
263	
264			// Attempt two: look for a suitable block in the union.
265			BitSet candidates = newBlocksBitSet(mth);
266			for (BlockNode candidate : bitSetToBlocks(mth, union)) {
267				if (isCandidateForOutBlock(mth, thenBlock, elseBlock, candidate)) {
268					candidates.set(candidate.getPos());
269				}
270			}
271	
272			BlockNode bottom = getBottomBlock(bitSetToBlocks(mth, candidates), true);
273			if (bottom != null) {
274				return bottom;
275			}
276	
277			// Attempt three: fallback to path cross again
278			return getPathCross(mth, thenBlock, elseBlock);
279		}
