281		static boolean isCandidateForOutBlock(MethodNode mth, BlockNode thenBlock, BlockNode elseBlock, BlockNode candidate) {
282			// a candidate block requires:
283			// - >1 predecessor
284			// - each predecessor has a clean path from elseBlock or thenBlock, and there exist predecessors
285			// covering both cases
286			// - inside the union of the two dom frontiers
287	
288			if (candidate.getPredecessors().size() < 2) {
289				return false; // block has only one pred, and so can't be the outblock
290			}
291	
292			BitSet coverageThenPreds = newBlocksBitSet(mth);
293			BitSet coverageElsePreds = newBlocksBitSet(mth);
294	
295			if (candidate == elseBlock) {
296				coverageElsePreds.set(candidate.getPos());
297			}
298			if (candidate == thenBlock) {
299				coverageThenPreds.set(candidate.getPos());

220			} else {
221				code.add("while (");
222				conditionGen.add(code, condition);
223				code.add(") {");
224				CodeGenUtils.addCodeComments(code, mth, condInsn);
225				makeRegionIndent(code, region.getBody());
226				code.startLine('}');
227			}
228		}
